{
  "manifest_version": 3,
  "name": "OpenEnsemble Bridge",
  "short_name": "OE Bridge",
  "version": "0.8.1",
  "description": "Ask, clip, compare, block ads and trackers locally, teach browser procedures, watch fields, and run confirmed tasks with scoped access.",
  "permissions": ["tabs", "storage", "scripting", "activeTab", "alarms", "sidePanel", "contextMenus", "declarativeNetRequestWithHostAccess", "declarativeNetRequestFeedback"],
  "omnibox": { "keyword": "oe" },
  "side_panel": { "default_path": "sidepanel.html" },
  "host_permissions": ["<all_urls>"],
  "background": {
    "service_worker": "background.js",
    "type": "module"
  },
  "declarative_net_request": {
    "rule_resources": [
      { "id": "oe_ads", "enabled": true, "path": "rules/ads.json" },
      { "id": "oe_trackers", "enabled": true, "path": "rules/trackers.json" },
      { "id": "oe_annoyances", "enabled": false, "path": "rules/annoyances.json" },
      { "id": "oe_surrogates", "enabled": true, "path": "rules/surrogates.json" }
    ]
  },
  "web_accessible_resources": [
    {
      "resources": ["surrogates/*.js"],
      "matches": ["<all_urls>"],
      "use_dynamic_url": false
    }
  ],
  "icons": {
    "16": "icons/oe-bridge-16.png",
    "32": "icons/oe-bridge-32.png",
    "48": "icons/oe-bridge-48.png",
    "128": "icons/oe-bridge-128.png"
  },
  "content_scripts": [
    {
      "matches": ["http://*/*", "https://*/*"],
      "js": ["content-cosmetic.js", "content-adblock.js"],
      "run_at": "document_start",
      "all_frames": true,
      "match_about_blank": true,
      "match_origin_as_fallback": true
    },
    {
      "matches": ["<all_urls>"],
      "js": ["content-banner.js"],
      "run_at": "document_idle",
      "all_frames": false
    },
    {
      "matches": ["<all_urls>"],
      "js": ["content-observe.js"],
      "run_at": "document_idle",
      "all_frames": false
    },
    {
      "matches": ["<all_urls>"],
      "js": ["content-field-picker.js"],
      "run_at": "document_idle",
      "all_frames": false
    }
  ],
  "action": {
    "default_popup": "popup.html",
    "default_title": "OpenEnsemble Bridge",
    "default_icon": {
      "16": "icons/oe-bridge-16.png",
      "32": "icons/oe-bridge-32.png",
      "48": "icons/oe-bridge-48.png",
      "128": "icons/oe-bridge-128.png"
    }
  }
}

// OE Bridge field picker. Dormant until extension UI explicitly starts it.
// It returns one selector and one bounded value; never page HTML or context.
(() => {
  if (globalThis.__oeFieldPickerInstalled) return;
  globalThis.__oeFieldPickerInstalled = true;

  let active = false;
  let hovered = null;
  let host = null;
  let pickerMessage = null;
  const liveMonitors = new Map();

  const cssString = value => String(value).replace(/\\/g, '\\\\').replace(/"/g, '\\"');
  const compact = (value, max = 160) => String(value || '').replace(/\s+/g, ' ').trim().slice(0, max);

  function unique(selector) {
    try { return document.querySelectorAll(selector).length === 1; } catch { return false; }
  }

  function selectorFor(element) {
    const tag = element.localName;
    if (element.id) {
      const selector = `#${CSS.escape(element.id)}`;
      if (unique(selector)) return selector;
    }
    for (const name of ['data-testid', 'data-test', 'data-price', 'itemprop', 'aria-label', 'name']) {
      const value = compact(element.getAttribute(name), 120);
      if (!value) continue;
      const selector = `${tag}[${name}="${cssString(value)}"]`;
      if (unique(selector)) return selector;
    }
    const stableClasses = [...element.classList]
      .filter(value => /^[A-Za-z_-][A-Za-z0-9_-]{0,48}$/.test(value) && !/\d{5,}/.test(value))
      .slice(0, 2);
    if (stableClasses.length) {
      const selector = `${tag}${stableClasses.map(value => `.${CSS.escape(value)}`).join('')}`;
      if (unique(selector)) return selector;
    }
    const parts = [];
    let node = element;
    while (node && node.nodeType === Node.ELEMENT_NODE && node !== document.body && parts.length < 7) {
      const local = node.localName;
      const siblings = node.parentElement
        ? [...node.parentElement.children].filter(child => child.localName === local)
        : [];
      const suffix = siblings.length > 1 ? `:nth-of-type(${siblings.indexOf(node) + 1})` : '';
      parts.unshift(`${local}${suffix}`);
      const selector = parts.join(' > ');
      if (unique(selector)) return selector;
      node = node.parentElement;
    }
    return parts.join(' > ');
  }

  function anchorsFor(element, ownText) {
    const anchors = [];
    const add = (text, relation) => {
      const normalized = compact(text, 120);
      if (normalized && normalized !== ownText && !anchors.some(row => row.text === normalized)) {
        anchors.push({ text: normalized, relation });
      }
    };
    add(element.getAttribute('aria-label'), 'near');
    add(element.previousElementSibling?.textContent, 'before');
    add(element.nextElementSibling?.textContent, 'after');
    const labelledBy = element.getAttribute('aria-labelledby');
    if (labelledBy) add(document.getElementById(labelledBy)?.textContent, 'near');
    const parentText = compact(element.parentElement?.textContent, 120);
    if (parentText && parentText.length <= 120) add(parentText, 'parent');
    return anchors.slice(0, 5);
  }

  function inferField(element, value) {
    const itemprop = compact(element.getAttribute('itemprop'), 64).toLowerCase();
    const currency = /(?:\bUSD\b|\$)/i.test(value) ? 'USD'
      : /(?:\bEUR\b|€)/i.test(value) ? 'EUR'
        : /(?:\bGBP\b|£)/i.test(value) ? 'GBP'
          : /(?:\bJPY\b|¥)/i.test(value) ? 'JPY' : null;
    if (itemprop.includes('price') || currency) return { property: 'price', parser: { type: 'price', currency } };
    if (itemprop.includes('availability') || /\b(?:in stock|out of stock|sold out|available|unavailable|pre-?order)\b/i.test(value)) {
      return { property: 'availability', parser: { type: 'availability' } };
    }
    if (/[-+]?\d[\d.,'\s]*/.test(value)) return { property: 'value', parser: { type: 'number' } };
    return { property: 'text', parser: { type: 'text' } };
  }

  function setHover(element) {
    if (hovered === element) return;
    if (hovered) hovered.style.removeProperty('outline');
    hovered = element;
    if (hovered) hovered.style.setProperty('outline', '3px solid #f59e0b', 'important');
  }

  function cleanup(notify = false) {
    if (!active) return;
    active = false;
    setHover(null);
    host?.remove();
    host = null;
    pickerMessage = null;
    document.removeEventListener('mouseover', onHover, true);
    document.removeEventListener('click', onPick, true);
    document.removeEventListener('keydown', onKey, true);
    if (notify) chrome.runtime.sendMessage({ type: 'field_watch_picker_cancelled' }).catch(() => {});
  }

  function onHover(event) {
    const element = event.target instanceof Element ? event.target : null;
    if (!element || element === host || host?.contains(element)) return;
    setHover(element);
  }

  function onKey(event) {
    if (event.key !== 'Escape') return;
    event.preventDefault();
    event.stopImmediatePropagation();
    cleanup(true);
  }

  function onPick(event) {
    const element = event.target instanceof Element ? event.target : null;
    if (!element || element === host || host?.contains(element)) return;
    event.preventDefault();
    event.stopImmediatePropagation();
    if (element.matches('html, body, main, section, article, form, script, style, iframe, svg, canvas, input, textarea, select, [contenteditable="true"]')) {
      pickerMessage?.replaceChildren('That area is too broad or sensitive for a standing watch. Pick the displayed value itself.');
      return;
    }
    const value = compact(element.innerText || element.textContent || element.getAttribute('content'), 512);
    const selector = selectorFor(element);
    if (!value || value.length > 240 || element.children.length > 5 || !selector || !unique(selector)) {
      pickerMessage?.replaceChildren('That item cannot be pinned reliably. Try the visible value itself.');
      return;
    }
    const inferred = inferField(element, value);
    const selection = {
      selector,
      anchors: anchorsFor(element, value),
      value,
      property: inferred.property,
      parser: inferred.parser,
      tag: element.localName,
    };
    cleanup(false);
    chrome.runtime.sendMessage({ type: 'field_watch_picked', selection }).catch(() => {});
  }

  function start() {
    cleanup(false);
    active = true;
    host = document.createElement('div');
    host.style.cssText = 'all:initial;position:fixed;z-index:2147483647;top:12px;left:50%;transform:translateX(-50%);';
    const root = host.attachShadow({ mode: 'closed' });
    const bar = document.createElement('div');
    bar.style.cssText = 'font:600 13px -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:#3b2f08;background:#fffbeb;border:2px solid #f59e0b;border-radius:9px;padding:9px 12px;box-shadow:0 5px 22px rgba(0,0,0,.24);display:flex;gap:12px;align-items:center;max-width:680px;';
    const message = document.createElement('span');
    pickerMessage = message;
    message.dataset.message = 'true';
    message.textContent = 'Click the exact value OE should watch. Nothing else on the page will be saved.';
    const cancel = document.createElement('button');
    cancel.textContent = 'Cancel';
    cancel.style.cssText = 'font:600 12px inherit;border:1px solid #b45309;border-radius:5px;background:#fff;color:#92400e;padding:5px 8px;cursor:pointer;';
    cancel.addEventListener('click', event => { event.preventDefault(); event.stopPropagation(); cleanup(true); });
    bar.append(message, cancel);
    root.append(bar);
    document.documentElement.append(host);
    document.addEventListener('mouseover', onHover, true);
    document.addEventListener('click', onPick, true);
    document.addEventListener('keydown', onKey, true);
  }

  function canonicalUrl(value) {
    try {
      const url = new URL(String(value || ''));
      url.hash = '';
      return url.href;
    } catch { return null; }
  }

  function stopLiveMonitor(watchId) {
    const current = liveMonitors.get(String(watchId || ''));
    if (!current) return;
    clearTimeout(current.timer);
    current.observer.disconnect();
    liveMonitors.delete(String(watchId));
  }

  function startLiveMonitor(message) {
    const watchId = String(message.watchId || '').slice(0, 100);
    const selector = String(message.selector || '').slice(0, 500);
    const exactUrl = canonicalUrl(message.exactUrl);
    const locatorFingerprint = String(message.locatorFingerprint || '').slice(0, 160);
    if (!watchId || !selector || !exactUrl || exactUrl !== canonicalUrl(location.href) || !locatorFingerprint) return;
    let matches;
    try { matches = document.querySelectorAll(selector); } catch { return; }
    if (matches.length !== 1) return;
    const element = matches[0];
    if (element.matches('input,textarea,select,[contenteditable="true"]')) return;
    stopLiveMonitor(watchId);
    const state = { observer: null, timer: null, last: compact(element.innerText || element.textContent || element.getAttribute('content'), 512) };
    const emit = () => {
      state.timer = null;
      if (exactUrl !== canonicalUrl(location.href) || !element.isConnected) {
        stopLiveMonitor(watchId);
        return;
      }
      const value = compact(element.innerText || element.textContent || element.getAttribute('content'), 512);
      if (!value || value === state.last) return;
      state.last = value;
      chrome.runtime.sendMessage({
        type: 'field_watch_live_observation', watchId, pageUrl: exactUrl,
        value, locatorFingerprint,
      }).catch(() => {});
    };
    state.observer = new MutationObserver(() => {
      clearTimeout(state.timer);
      state.timer = setTimeout(emit, 500);
    });
    state.observer.observe(element, { subtree: true, childList: true, characterData: true, attributes: true, attributeFilter: ['content', 'aria-label'] });
    liveMonitors.set(watchId, state);
  }

  chrome.runtime.onMessage.addListener(message => {
    if (message?.type === 'oe_field_watch_picker_start') start();
    if (message?.type === 'oe_field_watch_picker_stop') cleanup(false);
    if (message?.type === 'oe_field_watch_monitor_start') startLiveMonitor(message);
    if (message?.type === 'oe_field_watch_monitor_stop') stopLiveMonitor(message.watchId);
  });
})();

// Browser-only device pairing helpers. This module deliberately has no
// dependency on background.js, so a legacy connection remains untouched until
// a newly approved browser credential is ready for challenge-response.

export const PAIRING_PROTOCOL_VERSION = 1;
export const PAIRING_INFO_PATH = '/api/browser/pairing/info';
export const PAIRING_REQUEST_PATH = '/api/browser/pairing/requests';
export const PAIRING_CLAIM_PATH = '/api/browser/pairing/claims';

export class PairingError extends Error {
  constructor(message, { code = 'pairing_error', status = null } = {}) {
    super(message);
    this.name = 'PairingError';
    this.code = code;
    this.status = status;
  }
}

export function normalizeServerOrigin(value) {
  if (!value) return null;
  try {
    const url = new URL(String(value).trim());
    if (url.protocol !== 'http:' && url.protocol !== 'https:') return null;
    return url.origin;
  } catch {
    return null;
  }
}

export function buildDiscoveryCandidates({ explicitUrl, activeTabUrl, configuredUrl } = {}) {
  const candidates = [];
  const add = (value) => {
    const origin = normalizeServerOrigin(value);
    if (origin && !candidates.includes(origin)) candidates.push(origin);
  };
  add(explicitUrl);
  add(activeTabUrl);
  add(configuredUrl);
  add('http://localhost:3737');
  add('http://127.0.0.1:3737');
  return candidates;
}

function normalizePath(value, fallback) {
  if (typeof value !== 'string' || !value.startsWith('/') || value.startsWith('//')) return fallback;
  return value;
}

function withTimeout(timeoutMs, externalSignal) {
  const controller = new AbortController();
  const onAbort = () => controller.abort(externalSignal?.reason);
  if (externalSignal) {
    if (externalSignal.aborted) controller.abort(externalSignal.reason);
    else externalSignal.addEventListener('abort', onAbort, { once: true });
  }
  const timer = setTimeout(() => controller.abort(new DOMException('Timed out', 'TimeoutError')), timeoutMs);
  return {
    signal: controller.signal,
    dispose() {
      clearTimeout(timer);
      externalSignal?.removeEventListener('abort', onAbort);
    },
  };
}

async function fetchJson(url, options, { fetchImpl, timeoutMs = 5000, signal } = {}) {
  const timed = withTimeout(timeoutMs, signal);
  try {
    const response = await fetchImpl(url, { ...options, signal: timed.signal });
    const body = await response.json().catch(() => null);
    if (!response.ok) {
      const detail = body?.error || body?.message || `HTTP ${response.status}`;
      throw new PairingError(detail, { code: 'http_error', status: response.status });
    }
    if (!body || typeof body !== 'object') {
      throw new PairingError('OE returned an invalid pairing response.', { code: 'invalid_response' });
    }
    return body;
  } catch (error) {
    if (error instanceof PairingError) throw error;
    if (timed.signal.aborted) throw new PairingError('OE did not respond in time.', { code: 'timeout' });
    throw new PairingError(error?.message || 'Could not reach OE.', { code: 'network_error' });
  } finally {
    timed.dispose();
  }
}

export async function discoverPairingService({
  candidates,
  fetchImpl = globalThis.fetch,
  timeoutMs = 3000,
  signal,
} = {}) {
  if (typeof fetchImpl !== 'function') throw new PairingError('Browser fetch is unavailable.');
  const tried = [];
  for (const candidate of candidates || []) {
    const serverUrl = normalizeServerOrigin(candidate);
    if (!serverUrl || tried.includes(serverUrl)) continue;
    tried.push(serverUrl);
    try {
      const info = await fetchJson(serverUrl + PAIRING_INFO_PATH, {
        method: 'GET',
        credentials: 'omit',
        cache: 'no-store',
        referrerPolicy: 'no-referrer',
      }, { fetchImpl, timeoutMs, signal });
      if (info.service !== 'openensemble-browser-pairing' || Number(info.version) !== PAIRING_PROTOCOL_VERSION) continue;
      return {
        serverUrl,
        requestPath: normalizePath(info.requestPath, PAIRING_REQUEST_PATH),
        claimPath: normalizePath(info.claimPath, PAIRING_CLAIM_PATH),
      };
    } catch (error) {
      if (signal?.aborted) throw error;
      // A failed candidate is normal during discovery; continue probing.
    }
  }
  throw new PairingError(
    tried.length
      ? `Couldn't find an OE server that supports secure browser pairing. Tried: ${tried.join(', ')}.`
      : 'No valid OE server address was available.',
    { code: 'not_found' },
  );
}

function assertPublicJwk(jwk) {
  if (!jwk || jwk.kty !== 'EC' || jwk.crv !== 'P-256' || !jwk.x || !jwk.y) {
    throw new PairingError('Could not create a valid browser identity key.', { code: 'invalid_key' });
  }
}

export async function generatePairingKeypair({ subtle = globalThis.crypto?.subtle } = {}) {
  if (!subtle) throw new PairingError('Secure browser cryptography is unavailable.', { code: 'crypto_unavailable' });
  const keypair = await subtle.generateKey({ name: 'ECDSA', namedCurve: 'P-256' }, true, ['sign', 'verify']);
  const [publicKeyJwk, privateKeyJwk] = await Promise.all([
    subtle.exportKey('jwk', keypair.publicKey),
    subtle.exportKey('jwk', keypair.privateKey),
  ]);
  assertPublicJwk(publicKeyJwk);
  if (!privateKeyJwk?.d) throw new PairingError('Could not export the browser identity key.', { code: 'invalid_key' });
  return { publicKeyJwk, privateKeyJwk };
}

function resolveEndpoint(serverUrl, path, fallback) {
  const origin = normalizeServerOrigin(serverUrl);
  if (!origin) throw new PairingError('The OE server address is invalid.', { code: 'invalid_server_url' });
  return origin + normalizePath(path, fallback);
}

export async function requestBrowserPairing({
  serverUrl,
  requestPath,
  publicKeyJwk,
  browserName,
  extensionVersion,
  sharedProfile,
  fetchImpl = globalThis.fetch,
  timeoutMs = 5000,
  signal,
} = {}) {
  assertPublicJwk(publicKeyJwk);
  const body = await fetchJson(resolveEndpoint(serverUrl, requestPath, PAIRING_REQUEST_PATH), {
    method: 'POST',
    credentials: 'omit',
    cache: 'no-store',
    referrerPolicy: 'no-referrer',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      publicKeyJwk,
      browserName: String(browserName || '').trim().slice(0, 120),
      extensionVersion: String(extensionVersion || '').trim().slice(0, 32),
      sharedProfile: Boolean(sharedProfile),
    }),
  }, { fetchImpl, timeoutMs, signal });
  if (!body.requestId || !body.claimSecret || !body.userCode || !body.expiresAt) {
    throw new PairingError('OE returned an incomplete pairing request.', { code: 'invalid_response' });
  }
  const expiresAt = new Date(body.expiresAt).getTime();
  if (!Number.isFinite(expiresAt) || expiresAt <= Date.now()) {
    throw new PairingError('OE returned an expired pairing request.', { code: 'invalid_response' });
  }
  let approvalUrl = null;
  if (body.approvalUrl) {
    try {
      const serverOrigin = normalizeServerOrigin(serverUrl);
      const parsed = new URL(body.approvalUrl, serverOrigin);
      // Discovery can begin from an arbitrary active tab. Never let a server
      // that merely imitates the discovery marker turn this button into an
      // off-origin phishing link.
      if ((parsed.protocol === 'http:' || parsed.protocol === 'https:') && parsed.origin === serverOrigin) {
        approvalUrl = parsed.href;
      }
    } catch { /* optional */ }
  }
  return {
    requestId: String(body.requestId),
    claimSecret: [REDACTED],
    userCode: String(body.userCode),
    expiresAt,
    pollIntervalMs: Math.min(10_000, Math.max(1_000, Number(body.pollIntervalMs) || 2_000)),
    approvalUrl,
  };
}

export async function claimBrowserPairing({
  serverUrl,
  claimPath,
  requestId,
  claimSecret,
  fetchImpl = globalThis.fetch,
  timeoutMs = 5000,
  signal,
} = {}) {
  if (!requestId || !claimSecret) {
    throw new PairingError('The pending pairing request is incomplete.', { code: 'invalid_pending_request' });
  }
  const body = await fetchJson(resolveEndpoint(serverUrl, claimPath, PAIRING_CLAIM_PATH), {
    method: 'POST',
    credentials: 'omit',
    cache: 'no-store',
    referrerPolicy: 'no-referrer',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ requestId, claimSecret }),
  }, { fetchImpl, timeoutMs, signal });
  const status = String(body.status || '');
  if (!['pending', 'approved', 'denied', 'expired'].includes(status)) {
    throw new PairingError('OE returned an unknown pairing status.', { code: 'invalid_response' });
  }
  if (status === 'approved' && !body.credentialId) {
    throw new PairingError('OE approved pairing without issuing a browser credential.', { code: 'invalid_response' });
  }
  return {
    status,
    credentialId: body.credentialId ? String(body.credentialId) : null,
    userName: typeof body.userName === 'string' ? body.userName.trim() : '',
    expiresAt: body.expiresAt ? new Date(body.expiresAt).getTime() : null,
    pollIntervalMs: body.pollIntervalMs
      ? Math.min(10_000, Math.max(1_000, Number(body.pollIntervalMs)))
      : null,
  };
}

// Pure local matcher helpers for OE's generic project-suggestion badge.
// This module never receives project names or page bodies.

const STOP = new Set(['about', 'after', 'from', 'have', 'page', 'price', 'product', 'review', 'that', 'this', 'with', 'your']);

function pageTokens(value) {
  return new Set(String(value || '')
    .normalize('NFKD')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .split(/\s+/)
    .filter(word => word.length >= 4 && word.length <= 28 && !STOP.has(word)));
}

function hostOf(url) {
  try {
    const parsed = new URL(String(url || ''));
    if (!['http:', 'https:'].includes(parsed.protocol)) return null;
    return parsed.hostname.toLowerCase().replace(/^www\./, '').replace(/\.$/, '');
  } catch { return null; }
}

export function normalizeSuggestionMatchers(input) {
  if (!Array.isArray(input)) return [];
  return input.slice(0, 100).flatMap(raw => {
    const id = String(raw?.id || '').slice(0, 100);
    if (!/^bsm_[A-Za-z0-9_-]{8,80}$/.test(id)) return [];
    const domains = [...new Set((Array.isArray(raw.domains) ? raw.domains : [])
      .map(value => String(value || '').toLowerCase().replace(/^www\./, '').replace(/\.$/, ''))
      .filter(value => /^[a-z0-9.-]{1,253}$/.test(value) && value.includes('.')))]
      .slice(0, 6);
    const keywords = [...new Set((Array.isArray(raw.keywords) ? raw.keywords : [])
      .map(value => String(value || '').toLowerCase())
      .filter(value => /^[a-z0-9]{4,28}$/.test(value)))]
      .slice(0, 12);
    const excludedDomains = [...new Set((Array.isArray(raw.excludedDomains) ? raw.excludedDomains : [])
      .map(value => String(value || '').toLowerCase().replace(/^www\./, '').replace(/\.$/, ''))
      .filter(value => /^[a-z0-9.-]{1,253}$/.test(value) && value.includes('.')))]
      .slice(0, 20);
    if (!domains.length && !keywords.length) return [];
    return [{
      id, domains, excludedDomains, keywords,
      minKeywordMatches: Math.max(1, Math.min(4, Number(raw.minKeywordMatches) || 1)),
      updatedAt: typeof raw.updatedAt === 'string' ? raw.updatedAt.slice(0, 40) : null,
    }];
  });
}

/** Return only an opaque matcher id and score; labels stay on the server. */
export function matchSuggestionForPage(matchers, { url, title } = {}) {
  const host = hostOf(url);
  if (!host) return null;
  const words = pageTokens(`${title || ''} ${host.replace(/\./g, ' ')}`);
  let best = null;
  for (const matcher of normalizeSuggestionMatchers(matchers)) {
    if (matcher.excludedDomains.some(domain => host === domain || host.endsWith(`.${domain}`))) continue;
    const domainMatch = matcher.domains.some(domain => host === domain || host.endsWith(`.${domain}`));
    const hits = matcher.keywords.filter(keyword => words.has(keyword));
    if (!domainMatch && hits.length < matcher.minKeywordMatches) continue;
    const score = (domainMatch ? 10 : 0) + hits.length;
