    let best = null;
    let bestScore = 0;
    for (let index = 0; index < chain.length; index++) {
      const element = chain[index];
      const score = adSignalScore(element) - (index * 0.05);
      if (score > bestScore && reasonableBounds(element, score >= 7)) {
        best = element;
        bestScore = score;
      }
    }
    if (best) return best;

    const media = chain.find(element => element.matches(MEDIA_SELECTOR));
    if (media && reasonableBounds(media)) {
      let candidate = media;
      const mediaRect = media.getBoundingClientRect();
      for (let index = chain.indexOf(media) + 1; index < Math.min(chain.length, chain.indexOf(media) + 4); index++) {
        const parent = chain[index];
        const rect = parent.getBoundingClientRect();
        const areaRatio = (rect.width * rect.height) / Math.max(1, mediaRect.width * mediaRect.height);
        if (areaRatio <= 2.5 && parent.children.length <= 12 && reasonableBounds(parent)) candidate = parent;
      }
      return candidate;
    }

    return reasonableBounds(target) ? target : null;
  }

  function highSignalSelector(element) {
    const tag = element.localName;
    for (const name of ['data-ad', 'data-ad-slot', 'data-ad-unit', 'data-google-query-id']) {
      if (!element.hasAttribute(name)) continue;
      const broad = `${tag}[${name}]`;
      if (selectorMatches(broad, element)) return broad;
    }

    for (const name of ['aria-label', 'data-testid', 'data-test']) {
      const value = compact(element.getAttribute(name), 120);
      if (!value || (name === 'aria-label'
        ? !GENERIC_AD_LABEL.test(value)
        : (!AD_HINT.test(value) || !stableToken(value)))) continue;
      const selector = `${tag}[${name}="${cssString(value)}"]`;
      if (selectorMatches(selector, element)) return selector;
    }

    const signalClasses = [...element.classList].filter(token => stableToken(token) && AD_HINT.test(token));
    for (const token of signalClasses) {
      const selector = `${tag}.${CSS.escape(token)}`;
      if (selectorMatches(selector, element)) return selector;
    }
    return null;
  }

  function segmentFor(element, includePosition = false) {
    const tag = element.localName;
    const id = compact(element.id, 96);
    if (id && stableToken(id)) return `#${CSS.escape(id)}`;

    for (const name of ['data-testid', 'data-test', 'role']) {
      const value = compact(element.getAttribute(name), 120);
      if (value && value.length >= 2 && stableToken(value)) {
        return `${tag}[${name}="${cssString(value)}"]`;
      }
    }

    const classes = [...element.classList].filter(stableToken).slice(0, 2);
    let segment = `${tag}${classes.map(token => `.${CSS.escape(token)}`).join('')}`;
    if (includePosition && element.parentElement) {
      const siblings = [...element.parentElement.children].filter(child => child.localName === tag);
      if (siblings.length > 1) segment += `:nth-of-type(${siblings.indexOf(element) + 1})`;
    }
    return segment;
  }

  function selectorFor(element) {
    const highSignal = highSignalSelector(element);
    if (highSignal) return highSignal;

    const id = compact(element.id, 96);
    if (id && stableToken(id)) {
      const selector = `#${CSS.escape(id)}`;
      if (selectorMatches(selector, element)) return selector;
    }

    const classSelector = segmentFor(element, false);
    const classMatches = selectorMatches(classSelector, element);
    if (classMatches?.length === 1) return classSelector;

    const parts = [];
    let node = element;
    while (node && node instanceof Element && !node.matches('html,body,main') && parts.length < 7) {
      parts.unshift(segmentFor(node, true));
      const selector = parts.join(' > ');
      const matches = selectorMatches(selector, element);
      if (matches?.length === 1) return selector;
      node = node.parentElement;
    }
    return null;
  }

  function ensureStyle() {
    if (!document.documentElement) return;
    const expected = `[${HIDDEN_ATTRIBUTE}][${HIDDEN_ATTRIBUTE}][${HIDDEN_ATTRIBUTE}]{display:none !important;visibility:hidden !important;}`;
    if (styleElement?.isConnected && styleElement.textContent === expected) return;
    styleElement?.remove();
    styleElement = document.createElement('style');
    styleElement.textContent = expected;
    document.documentElement.appendChild(styleElement);
  }

  function clearHidden() {
    try {
      for (const element of document.querySelectorAll(`[${HIDDEN_ATTRIBUTE}]`)) {
        element.removeAttribute(HIDDEN_ATTRIBUTE);
      }
    } catch {}
    lastMatchedCount = 0;
  }

  function applyRules() {
    applyTimer = null;
    if (!document.documentElement) return;
    if (!enabled || !learnedRules.length) {
      stopObserver();
      clearHidden();
      return;
    }
    ensureObserver();
    ensureStyle();
    const matched = new Set();
    for (const rule of learnedRules) {
      const matches = selectorMatches(rule.selector);
      if (!matches) continue;
      for (const element of matches) {
        if (!isSafeTarget(element)) continue;
        matched.add(element);
        if (!element.hasAttribute(HIDDEN_ATTRIBUTE)) element.setAttribute(HIDDEN_ATTRIBUTE, 'true');
      }
    }
    for (const element of document.querySelectorAll(`[${HIDDEN_ATTRIBUTE}]`)) {
      if (!matched.has(element)) element.removeAttribute(HIDDEN_ATTRIBUTE);
    }
    lastMatchedCount = matched.size;
  }

  function scheduleApply(delay = 50) {
    if (applyTimer) return;
    applyTimer = setTimeout(applyRules, delay);
  }

  function ensureObserver() {
    if (observer || !document.documentElement) return;
    observer = new MutationObserver(() => scheduleApply(250));
    observer.observe(document.documentElement, {
      subtree: true,
      childList: true,
      attributes: true,
      attributeFilter: [
        HIDDEN_ATTRIBUTE, 'id', 'class', 'aria-label', 'role', 'data-testid', 'data-test',
        'data-ad', 'data-ad-slot', 'data-ad-unit', 'data-google-query-id',
      ],
    });
  }

  function stopObserver() {
    observer?.disconnect();
    observer = null;
  }

  function normalizeRules(rules) {
    if (!Array.isArray(rules)) return [];
    return rules
      .filter(rule => rule && typeof rule.id === 'string' && selectorSyntaxSafe(rule.selector))
      .slice(0, MAX_FRAME_RULES)
      .map(rule => ({ id: rule.id, selector: rule.selector }));
  }

  function setState(state) {
    if (!state?.ok) return;
    // A paused site keeps its learned rules on disk but applies nothing here,
    // and takes the list-driven cosmetic layer down with it. The bundled rules
    // and stylesheets are excluded declaratively; only element collapsing and
    // learned rules need telling.
    if (state.paused === true) {
      enabled = false;
      learnedRules = [];
      globalThis.__oeCosmeticDisable?.();
      scheduleApply(0);
      return;
    }
    enabled = state.enabled === true;
    if (typeof state.siteHost === 'string' && state.siteHost) currentSiteHost = state.siteHost.toLowerCase();
    if (typeof state.frameHost === 'string' && state.frameHost) currentFrameHost = state.frameHost.toLowerCase();
    learnedRules = normalizeRules(state.rules);
    scheduleApply(0);
  }

  function requestState() {
    try {
      chrome.runtime.sendMessage({ type: 'adblock_content_ready' }, response => {
        if (chrome.runtime.lastError) return;
        setState(response);
      });
    } catch {}
  }

  function refreshState(message) {
    const frameHost = currentFrameHost || (() => {
      const values = [location.href, globalThis.origin, location.origin];
      try { values.push(document.location.ancestorOrigins?.[0]); } catch {}
      for (const value of values) {
        try {
          const url = new URL(value);
          if (url.protocol === 'http:' || url.protocol === 'https:') return url.hostname.toLowerCase();
          if (url.protocol === 'blob:') {
            const owner = new URL(url.pathname);
            if (owner.protocol === 'http:' || owner.protocol === 'https:') return owner.hostname.toLowerCase();
          }
        } catch {}
      }
      return String(message?.siteHost || '').toLowerCase();
    })();
    setState({
      ok: true,
      enabled: message?.enabled === true,
      siteHost: message?.siteHost || currentSiteHost,
      frameHost,
      rules: Array.isArray(message?.rules)
        ? message.rules.filter(rule => rule?.frameHost === frameHost)
        : [],
    });
  }

  function showToast(message, { ruleId = null, isError = false } = {}) {
    clearTimeout(toastTimer);
    toastHost?.remove();
    toastHost = document.createElement('div');
    toastHost.style.cssText = 'all:initial;position:fixed;z-index:2147483647;top:14px;right:14px;max-width:360px;';
    toastShadow = toastHost.attachShadow({ mode: 'closed' });
    const card = document.createElement('div');
    card.setAttribute('role', isError ? 'alert' : 'status');
    card.setAttribute('aria-live', isError ? 'assertive' : 'polite');
    card.style.cssText = `font:600 12px/1.45 -apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;color:${isError ? '#7f1d1d' : '#14532d'};background:${isError ? '#fef2f2' : '#f0fdf4'};border:1px solid ${isError ? '#fca5a5' : '#86efac'};border-radius:8px;padding:9px 11px;box-shadow:0 6px 24px rgba(0,0,0,.22);display:flex;align-items:center;gap:9px;`;
    const label = document.createElement('span');
    label.textContent = message;
    card.append(label);
    if (ruleId) {
      const undo = document.createElement('button');
      undo.type = 'button';
      undo.textContent = 'Undo';
      undo.style.cssText = 'font:700 11px inherit;border:1px solid #4ade80;border-radius:5px;background:#fff;color:#166534;padding:4px 7px;cursor:pointer;';
      undo.addEventListener('click', () => {
        undo.disabled = true;
        chrome.runtime.sendMessage({ type: 'adblock_remove_learned_rule', ruleId }, response => {
          if (chrome.runtime.lastError || !response?.ok) {
            showToast(response?.error || 'Could not undo that rule.', { isError: true });
            return;
          }
          requestState();
          showToast('That learned ad rule was removed.');
        });
      });
      card.append(undo);
    }
    toastShadow.append(card);
    document.documentElement?.appendChild(toastHost);
    toastTimer = setTimeout(() => {
      toastHost?.remove();
      toastHost = null;
      toastShadow = null;
    }, ruleId ? 9_000 : 6_000);
  }

  function blockContextTarget() {
    if (!enabled) return { ok: false, error: 'Ad blocking is turned off in the OE Bridge popup.' };
    if (!lastContextTarget || Date.now() - lastContextAt > TARGET_TTL_MS || !lastContextTarget.isConnected) {
      return { ok: false, error: 'The clicked item expired. Right-click the ad again.' };
    }
    const candidate = chooseCandidate(lastContextTarget);
    if (!candidate) return { ok: false, error: 'That area is too broad or sensitive to learn safely.' };
    const selector = selectorFor(candidate);
    const matches = selector && selectorMatches(selector, candidate);
    if (!selector || !matches) return { ok: false, error: 'OE could not make a stable rule for that item.' };
    return {
      ok: true,
      selector,
      matchCount: matches.length,
      frameUrl: location.href,
      frameOrigin: globalThis.origin,
      frameHost: currentFrameHost,
      tag: candidate.localName,
      signalled: adSignalScore(candidate) > 0,
    };
  }

  document.addEventListener('contextmenu', event => {
    if (!event.isTrusted) return;
    const rawTarget = event.composedPath?.().find(node => node instanceof Element)
      || (event.target instanceof Element ? event.target : null);
    const target = documentReachableTarget(rawTarget);
    if (!target || isOwnedUi(target)) return;
    lastContextTarget = target;
    lastContextAt = Date.now();
  }, true);

  chrome.runtime.onMessage.addListener((message, _sender, sendResponse) => {
    if (message?.type === 'oe_adblock_block_context_target') {
      sendResponse(blockContextTarget());
      return;
    }
    if (message?.type === 'oe_adblock_refresh') {
      refreshState(message);
      return;
    }
    if (message?.type === 'oe_adblock_rule_saved') {
      showToast(`Blocked this ad and learned it for ${message.siteHost || 'this site'}.`, { ruleId: message.ruleId || null });
      return;
    }
    if (message?.type === 'oe_adblock_notice') {
      showToast(message.message || 'OE could not block that item.', { isError: message.isError !== false });
      return;
    }
    if (message?.type === 'oe_adblock_get_status') {
      sendResponse({ ok: true, enabled, matchedCount: lastMatchedCount });
    }
  });

  if (!document.documentElement) {
    document.addEventListener('readystatechange', () => scheduleApply(0), { once: true });
  }
  addEventListener('pageshow', event => {
    if (event.persisted) requestState();
  });
  requestState();
})();

// OE Bridge — side panel chat surface.
//
// Stays open while the user interacts with the page (this is the whole
// point vs the popup). Reads chat history from chrome.storage.local on
// load so the conversation survives panel close + reopen. Listens for
// chat_event / chat_done / chat_error messages from the background SW
// for the currently-streaming response.

const $ = (id) => document.getElementById(id);
const PANEL_REQUEST_TIMEOUT_MS = 5000;

async function withPanelTimeout(operation) {
  let timer;
  try {
    return await Promise.race([
      operation(),
      new Promise((_, reject) => {
        timer = setTimeout(() => reject(new Error('OE Bridge is not responding. Reload it from Extensions.')), PANEL_REQUEST_TIMEOUT_MS);
      }),
    ]);
  } finally {
    clearTimeout(timer);
  }
}

function requestPanelState(type) {
  return withPanelTimeout(() => chrome.runtime.sendMessage({ type }));
}

let _currentRequestId = null;
let _currentAssistantEl = null;
let _statusBadge = $('status');
let _voiceUserEl = null;
let _voiceRecorder = null;
let _voiceStream = null;
let _voiceChunks = [];
let _voiceStopTimer = null;
let _teachActive = false;
let _confirmationId = null;
let _fieldWatchSelection = null;
let _suggestionId = null;

function renderSuggestionAvailable(available) {
  $('suggestionCard').hidden = !available;
  if (!available) {
    _suggestionId = null;
    $('suggestionDetails').hidden = true;
    $('suggestionReason').textContent = '';
  }
}

function renderStatus(status) {
  const el = $('status');
  if (!el) return;
  if (status?.connected) {
    el.className = 'status ok';
    const userName = typeof status.userName === 'string' ? status.userName.trim() : '';
    el.textContent = userName ? `Connected ${userName}` : 'Connected';
  } else if (status?.lastError) {
    el.className = 'status bad';
    el.textContent = `Disconnected — ${String(status.lastError).slice(0, 60)}`;
  } else {
    el.className = 'status idle';
    el.textContent = 'Waiting…';
  }
}

async function refreshStatus() {
  try {
    const r = await requestPanelState('get_status');
    if (!r?.status) throw new Error('OE Bridge returned no connection status.');
    renderStatus(r.status);
  } catch (error) {
    renderStatus({ lastError: error?.message || String(error) });
  }
}

async function refreshSuggestion() {
  try {
    const response = await requestPanelState('suggestion_get');
    renderSuggestionAvailable(response?.ok && response.available);
  } catch {}
}

async function refreshTeachState() {
  try {
    const response = await requestPanelState('get_teach_state');
    _teachActive = Boolean(response?.active);
    const button = $('teachThisSite');
    button.textContent = _teachActive ? '■ Stop teaching' : '🎓 Teach this site';
    button.style.color = _teachActive ? '#b91c1c' : '';
    button.title = _teachActive
      ? 'Stop the current tab-scoped Teach session and erase its observation buffer.'
      : 'Observe your clicks and non-sensitive inputs on this tab and site for up to 15 minutes.';
  } catch {}
}

function renderActionConfirmation(confirmation) {
  _confirmationId = confirmation?.id || null;
  $('actionConfirmation').hidden = !_confirmationId;
  if (!_confirmationId) return;
  $('confirmationSummary').textContent = confirmation.summary || 'Allow this browser action once?';
  $('confirmationOrigin').textContent = [confirmation.pageTitle, confirmation.origin].filter(Boolean).join(' · ');
}

async function refreshActionConfirmation() {
  try {
    const response = await requestPanelState('get_pending_confirmation');
    renderActionConfirmation(response?.confirmation || null);
  } catch {}
}
chrome.runtime.onMessage.addListener((msg) => {
  if (msg?.type === 'status') renderStatus(msg.status);
  if (msg?.type === 'suggestion_available') renderSuggestionAvailable(msg.available === true);
  if (msg?.type === 'context_started') {
    appendMessage('user', msg.userText || 'Shared browser context');
    _currentRequestId = msg.requestId;
    _currentAssistantEl = appendMessage('assistant', '…');
  }
  if (msg?.type === 'clip_ready') openClipPicker(msg.capture).catch(error => {
    appendMessage('assistant', `[clip error: ${error?.message || String(error)}]`);
  });
  if (msg?.type === 'action_confirmation') renderActionConfirmation(msg.confirmation);
  if (msg?.type === 'field_watch_selection') renderFieldWatchSelection(msg.selection);
  if (msg?.type === 'field_watch_picker_cancelled') {
    $('fieldWatchMessage').textContent = 'Field selection cancelled.';
    $('fieldWatchPick').disabled = false;
  }
});

function appendMessage(role, text) {
  const empty = $('empty');
  if (empty) empty.remove();
  const msgsEl = $('messages');
  const div = document.createElement('div');
  div.className = `msg ${role}`;
  div.textContent = text || '';
  msgsEl.appendChild(div);
  msgsEl.scrollTop = msgsEl.scrollHeight;
  return div;
}

async function openClipPicker(capture) {
  $('clipPicker').hidden = false;
  $('clipSummary').textContent = capture?.title
    ? `${capture.kind === 'selection' ? 'Selection from' : 'Page'}: ${capture.title}`
    : 'Preparing page…';
  $('clipMessage').textContent = 'Loading your OE documents…';
  $('clipSave').disabled = true;
  const response = await chrome.runtime.sendMessage({ type: 'clip_targets' });
  if (!response?.ok) throw new Error(response?.error || 'could not load clip destinations');
  const select = $('clipTarget');
  select.replaceChildren();
  const create = document.createElement('option');
  create.value = 'new';
  create.textContent = '＋ New project document…';
  select.appendChild(create);
  for (const target of response.targets || []) {
    const option = document.createElement('option');
    option.value = String(target.id || '');
    option.textContent = `${target.kind === 'research' ? 'Research' : 'Document'} · ${target.label || target.id}`;
    select.appendChild(option);
  }
  select.value = select.options.length > 1 ? select.options[1].value : 'new';
  $('clipNewNameRow').hidden = select.value !== 'new';
  $('clipMessage').textContent = 'Only this captured excerpt will be sent when you press Save.';
  $('clipSave').disabled = false;
}

function renderFieldWatchSelection(selection) {
  _fieldWatchSelection = selection || null;
  const summary = $('fieldWatchSelection');
  const form = $('fieldWatchCreate');
  $('fieldWatchPick').disabled = false;
  if (!selection) {
    summary.hidden = true;
    form.hidden = true;
    return;
  }
  let host = '';
  try { host = new URL(selection.exactUrl).host; } catch {}
  summary.textContent = `Selected “${selection.initialValue || 'value'}”. Exact URL: ${selection.exactUrl}. Only selector ${selection.field?.selector || 'the pinned field'} will be read.`;
  summary.hidden = false;
  form.hidden = false;
  if (!$('fieldWatchLabel').value) {
    const property = selection.field?.property === 'price' ? 'price'
      : selection.field?.property === 'availability' ? 'availability' : 'value';
    $('fieldWatchLabel').value = `${selection.title || host || 'Page'} ${property}`.slice(0, 160);
  }
  $('fieldWatchConfirm').checked = false;
  $('fieldWatchMessage').textContent = 'Review the exact-field permission, then start the watch.';
}

function watchPredicateLabel(watch) {
  const type = watch?.predicate?.type || 'changed';
  if (type === 'changed') return 'when it changes';
  return `${type.replaceAll('_', ' ')} ${watch?.predicate?.target ?? ''}`.trim();
}

async function refreshFieldWatches() {
  const list = $('fieldWatchList');
  list.replaceChildren();
  try {
    const response = await chrome.runtime.sendMessage({ type: 'field_watch_list' });
    if (!response?.ok) throw new Error(response?.error || 'could not load field watches');
    const watches = response.watches || [];
    if (!watches.length) {
      const empty = document.createElement('span');
      empty.style.cssText = 'font-size:11px;color:#6b7280';
      empty.textContent = 'No active field watches.';
      list.appendChild(empty);
      return;
    }
    for (const watch of watches) {
      const row = document.createElement('div');
      row.className = 'field-watch-row';
      const details = document.createElement('div');
      const name = document.createElement('b');
      name.textContent = watch.label || 'Field watch';
      const meta = document.createElement('small');
      const current = watch.baseline?.displayValue || watch.baseline?.value;
      const execution = watch.execution?.mode === 'browser'
        ? 'checked by this paired browser'
        : 'checked privately by the OE server';
      meta.textContent = `${watch.url} · ${watchPredicateLabel(watch)} · ${execution} · ${current == null ? 'waiting for first reading' : `now ${current}`}`;
      details.append(name, meta);
      if (watch.lastError?.message) {
        const error = document.createElement('small');
        error.style.color = '#b45309';
        error.textContent = watch.lastError.message;
        details.append(error);
      }
      const revoke = document.createElement('button');
      revoke.textContent = 'Stop';
      revoke.dataset.watchId = String(watch.id || '');
      revoke.addEventListener('click', async () => {
        revoke.disabled = true;
        $('fieldWatchMessage').textContent = `Stopping “${watch.label || 'field watch'}”…`;
        try {
          const result = await chrome.runtime.sendMessage({ type: 'field_watch_revoke', watchId: watch.id });
          if (!result?.ok) throw new Error(result?.error || 'could not stop watch');
          $('fieldWatchMessage').textContent = `Stopped “${watch.label || 'field watch'}”. Its standing permission is revoked.`;
          await refreshFieldWatches();
        } catch (error) {
          $('fieldWatchMessage').textContent = error?.message || String(error);
          revoke.disabled = false;
        }
      });
      row.append(details, revoke);
      list.appendChild(row);
    }
  } catch (error) {
    const message = document.createElement('span');
    message.style.cssText = 'font-size:11px;color:#b91c1c';
    message.textContent = error?.message || String(error);
    list.appendChild(message);
  }
}

async function openFieldWatchPanel() {
  $('fieldWatchPanel').hidden = false;
  $('fieldWatchMessage').textContent = 'Loading field watches…';
  await refreshFieldWatches();
  try {
    const pending = await chrome.runtime.sendMessage({ type: 'field_watch_pending_get' });
    renderFieldWatchSelection(pending?.selection || null);
    if (!pending?.selection) $('fieldWatchMessage').textContent = 'Pick the exact value you want OE to watch.';
  } catch (error) {
    $('fieldWatchMessage').textContent = error?.message || String(error);
  }
}

async function loadHistory() {
  const msgsEl = $('messages');
  const placeholder = document.createElement('div');
  placeholder.id = 'empty';
  placeholder.className = 'empty';
  placeholder.textContent = 'Loading…';
  msgsEl.replaceChildren(placeholder);
  try {
    let r;
    try {
      r = await requestPanelState('chat_history_get');
      if (!Array.isArray(r?.history)) throw new Error('OE Bridge returned no chat history.');
    } catch {
      // Open saved chat even when worker messaging is unavailable.
      const saved = await withPanelTimeout(() => chrome.storage.local.get(['chat_history', 'chat_current']));
      r = { history: saved.chat_history, current: saved.chat_current };
    }
    // A live message or Clear may have replaced the loading placeholder.
    if (!placeholder.isConnected) return;
    const history = Array.isArray(r?.history) ? r.history : [];
    const current = r?.current || null;
    msgsEl.replaceChildren();
    if (!history.length && !current) {
      msgsEl.innerHTML = '<div id="empty" class="empty">No conversation yet. Ask Sydney something.</div>';
      return;
    }
    for (const m of history) appendMessage(m.role, m.text);
    if (current) {
      appendMessage('user', current.userText);
      _currentRequestId = current.requestId;
      _currentAssistantEl = appendMessage('assistant', current.assistantText || '…');
    }
  } catch (e) {
    if (!placeholder.isConnected) return;
    placeholder.textContent = `Couldn't load history: ${e?.message || String(e)} `;
    const retry = document.createElement('button');
    retry.type = 'button';
    retry.textContent = 'Retry';
    retry.addEventListener('click', loadHistory);
    placeholder.appendChild(retry);
  }
}

function startNewAssistantBubble() {
  _currentAssistantEl = appendMessage('assistant', '');
}

function appendToken(text) {
  if (!_currentAssistantEl) startNewAssistantBubble();
  if (_currentAssistantEl.textContent === '…') _currentAssistantEl.textContent = '';
  _currentAssistantEl.textContent += text;
  const msgsEl = $('messages');
  msgsEl.scrollTop = msgsEl.scrollHeight;
}

function appendToolLine(name, preview = null) {
  if (!_currentAssistantEl) startNewAssistantBubble();
  const line = document.createElement('div');
  line.className = 'tool-line';
  line.textContent = preview ? `↳ ${name}: ${String(preview).slice(0, 100)}` : `[${name}…]`;
  _currentAssistantEl.appendChild(line);
  const msgsEl = $('messages');
  msgsEl.scrollTop = msgsEl.scrollHeight;
}

async function sendChat(text) {
  const t = String(text || '').trim();
  if (!t) return;
  appendMessage('user', t);
  $('chatInput').value = '';
  _currentRequestId = `sp_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  _currentAssistantEl = null;
  startNewAssistantBubble();
  _currentAssistantEl.textContent = '…';
  try {
    const r = await chrome.runtime.sendMessage({ type: 'chat_send', requestId: _currentRequestId, text: t });
    if (!r?.ok) {
      _currentAssistantEl.textContent = `[error: ${r?.error || 'send failed'}]`;
    }
  } catch (e) {
    _currentAssistantEl.textContent = `[error: ${e?.message || String(e)}]`;
  }
}

chrome.runtime.onMessage.addListener((msg) => {
  if (!msg || msg.requestId !== _currentRequestId) return;
  if (msg.type === 'voice_transcript') {
    if (_voiceUserEl) _voiceUserEl.textContent = `🎙️ ${msg.transcript}`;
    if (!_currentAssistantEl) {
      _currentAssistantEl = appendMessage('assistant', '…');
    }
  } else if (msg.type === 'chat_event') {
    const ev = msg.event || {};
    if (ev.type === 'token' && typeof ev.text === 'string') appendToken(ev.text);
    else if (ev.type === 'tool_call') appendToolLine(ev.name);
    else if (ev.type === 'tool_result') appendToolLine(ev.name, ev.preview || ev.text);
    else if (ev.type === 'error') appendToken(`\n[error: ${ev.message || 'unknown'}]`);
  } else if (msg.type === 'chat_done') {
    _currentRequestId = null;
    _currentAssistantEl = null;
    _voiceUserEl = null;
  } else if (msg.type === 'chat_error') {
    appendToken(`\n[server error: ${msg.message || 'unknown'}]`);
    _currentRequestId = null;
    _currentAssistantEl = null;
    _voiceUserEl = null;
  }
});

function arrayBufferToBase64(buffer) {
  const bytes = new Uint8Array(buffer);
  let binary = '';
  for (let i = 0; i < bytes.length; i += 0x8000) {
    binary += String.fromCharCode(...bytes.subarray(i, i + 0x8000));
  }
  return btoa(binary);
}

function resetVoiceButton() {
  const button = $('pushToTalk');
  button.classList.remove('recording');
  button.textContent = '🎙️ Talk';
  button.title = 'The microphone is active only while recording.';
}

async function finishVoiceRecording() {
  clearTimeout(_voiceStopTimer);
  _voiceStopTimer = null;
  const recorder = _voiceRecorder;
  const stream = _voiceStream;
  const chunks = _voiceChunks;
  _voiceRecorder = null;
  _voiceStream = null;
  _voiceChunks = [];
  stream?.getTracks().forEach(track => track.stop());
  resetVoiceButton();
  if (!chunks.length) {
    appendMessage('assistant', 'No microphone audio was captured.');
    return;
  }
  const mimeType = recorder?.mimeType || chunks[0]?.type || 'audio/webm';
  const blob = new Blob(chunks, { type: mimeType });
  if (!blob.size || blob.size > 925_000) {
    appendMessage('assistant', 'That recording was too large. Keep voice messages under 12 seconds.');
    return;
  }
  _currentRequestId = `voice_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  _currentAssistantEl = null;
  _voiceUserEl = appendMessage('user', '🎙️ Transcribing…');
  try {
    const response = await chrome.runtime.sendMessage({
      type: 'voice_send',
      requestId: _currentRequestId,
      mimeType,
      base64: arrayBufferToBase64(await blob.arrayBuffer()),
      lang: navigator.language || '',
    });
    if (!response?.ok) throw new Error(response?.error || 'voice send failed');
  } catch (error) {
    appendMessage('assistant', `[voice error: ${error?.message || String(error)}]`);
    _currentRequestId = null;
    _voiceUserEl = null;
  }
}

async function togglePushToTalk() {
  if (_voiceRecorder) {
    if (_voiceRecorder.state !== 'inactive') _voiceRecorder.stop();
    return;
  }
  if (_currentRequestId) {
    appendMessage('assistant', 'Wait for the current reply to finish before recording another message.');
    return;
  }
  if (!navigator.mediaDevices?.getUserMedia || typeof MediaRecorder === 'undefined') {
    appendMessage('assistant', 'Microphone recording is not available in this browser.');
    return;
  }
  try {
    _voiceStream = await navigator.mediaDevices.getUserMedia({ audio: true });
    const preferred = ['audio/webm;codecs=opus', 'audio/ogg;codecs=opus', 'audio/webm']
      .find(type => MediaRecorder.isTypeSupported?.(type));
    _voiceChunks = [];
    _voiceRecorder = new MediaRecorder(_voiceStream, preferred ? { mimeType: preferred } : undefined);
    _voiceRecorder.addEventListener('dataavailable', event => { if (event.data?.size) _voiceChunks.push(event.data); });
    _voiceRecorder.addEventListener('stop', () => finishVoiceRecording().catch(error => {
      resetVoiceButton();
      appendMessage('assistant', `[voice error: ${error?.message || String(error)}]`);
    }), { once: true });
    _voiceRecorder.start(500);
    $('pushToTalk').classList.add('recording');
    $('pushToTalk').textContent = '■ Stop';
    $('pushToTalk').title = 'Microphone active — click to stop.';
    _voiceStopTimer = setTimeout(() => {
      if (_voiceRecorder?.state !== 'inactive') _voiceRecorder.stop();
    }, 12_000);
  } catch (error) {
    _voiceStream?.getTracks().forEach(track => track.stop());
    _voiceStream = null;
    _voiceRecorder = null;
    resetVoiceButton();
    appendMessage('assistant', `Microphone permission was not granted: ${error?.message || String(error)}`);
  }
}

