// OpenEnsemble Bridge — activity banner content script.
// Renders a small colored bar at the top of the page whenever a server-
// initiated read or media action targets THIS tab. Lets the user always
// see when their browser is being touched + click STOP to disconnect the
// extension immediately. Receives start/end events from background.js
// via chrome.runtime.sendMessage.

(function () {
  const HOST_ID = '__oe_bridge_banner_host__';
  let _hostEl = null;
  let _shadowRoot = null;
  let _hideTimer = null;
  // Lease state for THIS tab — 'active' keeps a persistent amber bar up so
  // the user always knows OE currently holds access here; 'suspended' (the
  // tab navigated away from the origin it was granted on) shows a grey
  // paused bar with a Resume button.
  let _leaseState = 'none'; // 'none' | 'active' | 'suspended'
  let _leaseExpiresAt = null;
  let _mode = 'activity'; // 'activity' | 'lease' — which button behavior is showing

  function ensureBanner() {
    // NB: the host is appended to documentElement, not body — checking
    // body.contains() here silently recreated (and stacked) the banner on
    // every call. Harmless when banners were transient; visible now that
    // the lease bar is persistent.
    if (_hostEl && document.documentElement.contains(_hostEl)) return _hostEl;
    _hostEl = document.createElement('div');
    _hostEl.id = HOST_ID;
    _hostEl.style.cssText = `
      position: fixed; top: 0; left: 0; right: 0; z-index: 2147483647;
      pointer-events: none; display: none;
    `;
    _shadowRoot = _hostEl.attachShadow({ mode: 'closed' });
    _shadowRoot.innerHTML = `
      <style>
        .bar {
          font: 600 12px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
          background: linear-gradient(90deg, #2563eb, #6366f1);
          color: #fff; padding: 7px 14px;
          display: flex; align-items: center; justify-content: space-between;
          box-shadow: 0 2px 8px rgba(0,0,0,0.18);
          pointer-events: auto;
        }
        .bar.lease { background: linear-gradient(90deg, #d97706, #f59e0b); }
        .bar.paused { background: linear-gradient(90deg, #475569, #64748b); }
        .label { flex: 1; min-width: 0; }
        .label code { background: rgba(255,255,255,0.18); padding: 1px 6px; border-radius: 4px; font-size: 11px; }
        .stop, .resume {
          background: rgba(255,255,255,0.18); color: #fff; border: none;
          padding: 4px 10px; border-radius: 4px; cursor: pointer; font: inherit; font-weight: 700;
          margin-left: 10px;
        }
        .stop:hover, .resume:hover { background: rgba(255,255,255,0.28); }
      </style>
      <div class="bar">
        <div class="label"></div>
        <button class="resume" type="button" style="display:none">Resume</button>
        <button class="stop" type="button">Disconnect</button>
      </div>
    `;
    _shadowRoot.querySelector('.stop').addEventListener('click', () => {
      if (_mode === 'lease') {
        // Revoking the lease is fail-safe, so the banner button may do it
        // directly; background broadcasts the state change back to us.
        try { chrome.runtime.sendMessage({ type: 'revoke_lease' }); } catch {}
        _leaseState = 'none';
        renderBase();
      } else {
        try { chrome.runtime.sendMessage({ type: 'disconnect' }); } catch {}
        hide();
      }
    });
    _shadowRoot.querySelector('.resume').addEventListener('click', () => {
      // Resume is the cheap re-consent after a cross-origin navigation
      // paused the lease. Success comes back via the oe_lease broadcast;
      // only refusals (sensitive page, no entry) need showing here.
      try {
        chrome.runtime.sendMessage({ type: 'resume_lease' }, (resp) => {
          if (chrome.runtime.lastError) return;
          if (resp && !resp.ok) {
            _shadowRoot.querySelector('.label').textContent = `⏸ ${resp.error || "couldn't resume"}`;
          }
        });
      } catch {}
    });
    document.documentElement.appendChild(_hostEl);
    return _hostEl;
  }

  function show(action) {
    ensureBanner();
    const labelMap = {
      read_page:     'reading',
      open_tab:      'opening',
      media_control: 'controlling media on',
      back:          'navigating back on',
      forward:       'navigating forward on',
      reload:        'reloading',
      close_tab:     'closing',
      focus_tab:     'focusing',
      screenshot:    'taking a screenshot of',
      click_xy:      'clicking on',
      type:          'typing on',
      keypress:      'pressing a key on',
    };
    const txt = labelMap[action] || `running ${action} on`;
    _mode = 'activity';
    const bar = _shadowRoot.querySelector('.bar');
    bar.classList.remove('lease', 'paused');
    _shadowRoot.querySelector('.resume').style.display = 'none';
    _shadowRoot.querySelector('.label').textContent = `OpenEnsemble is ${txt} this page`;
    _shadowRoot.querySelector('.stop').textContent = 'Disconnect';
    _hostEl.style.display = 'block';
    clearTimeout(_hideTimer);
    // Fall back ~1.5s after the last activity — to hidden, or to the
    // persistent lease bar if this tab is leased. For long-running reads
    // background.js sends a follow-up event so this gets reset.
    _hideTimer = setTimeout(renderBase, 1500);
  }

  // The banner's resting state: a persistent amber bar while this tab is
  // under an active lease, a grey paused bar while the lease is suspended
  // (tab left its granted origin), nothing otherwise.
  function renderBase() {
    clearTimeout(_hideTimer);
    if (_leaseState === 'none') { hide(); return; }
    ensureBanner();
    _mode = 'lease';
    const bar = _shadowRoot.querySelector('.bar');
    const label = _shadowRoot.querySelector('.label');
    const resume = _shadowRoot.querySelector('.resume');
    bar.classList.toggle('lease', _leaseState === 'active');
    bar.classList.toggle('paused', _leaseState === 'suspended');
    if (_leaseState === 'suspended') {
      label.textContent = '⏸ OpenEnsemble access paused — this tab moved to a different site';
      resume.style.display = 'inline-block';
      _shadowRoot.querySelector('.stop').textContent = 'Revoke';
    } else {
      const until = _leaseExpiresAt
        ? new Date(_leaseExpiresAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })
        : '';
      label.textContent = `🔓 OpenEnsemble has access to this tab${until ? ` until ${until}` : ''}`;
      resume.style.display = 'none';
      _shadowRoot.querySelector('.stop').textContent = 'Revoke access';
    }
    _hostEl.style.display = 'block';
  }

  function hide() {
    clearTimeout(_hideTimer);
    if (_hostEl) _hostEl.style.display = 'none';
  }

  // Capture-phase submit guard — defense in depth behind the broker's
  // refusal to click submit controls or fire requestSubmit. OE's injected
  // click/type/keypress helpers stamp window.__oeSyntheticActionTs in this
  // same isolated world; a submit event landing on a leased tab right
  // after an OE action gets blocked. User-initiated submits never carry
  // the stamp, so normal browsing is unaffected.
  document.addEventListener('submit', (e) => {
    // Guard while any lease entry exists for this tab (active OR
    // suspended) — a stale synthetic-action stamp should never ride
    // through a suspension.
    if (_leaseState === 'none') return;
    const ts = window.__oeSyntheticActionTs || 0;
    const confirmedTs = window.__oeConfirmedActionTs || 0;
    const explicitlyConfirmed = confirmedTs && confirmedTs === ts;
    if (ts && (Date.now() - ts) < 1500 && !explicitlyConfirmed) {
      e.preventDefault();
      e.stopImmediatePropagation();
      try { chrome.runtime.sendMessage({ type: 'oe_submit_blocked', url: location.href }); } catch {}
    }
  }, true);

  // Visual click indicator — a pulsing ring at the (x, y) coordinate
  // OE is about to click. Lets the user see exactly where Chey is
  // acting on the page rather than just reading her chat narration.
  function showClickRing(x, y) {
    const host = document.createElement('div');
    host.style.cssText = 'position:fixed;left:0;top:0;width:0;height:0;z-index:2147483647;pointer-events:none;';
    const sh = host.attachShadow({ mode: 'closed' });
    sh.innerHTML = `
      <style>
        @keyframes oeClickRing {
          0%   { transform: translate(-50%, -50%) scale(0.4); opacity: 0.9; }
          100% { transform: translate(-50%, -50%) scale(2.4); opacity: 0; }
        }
        .ring {
          position: fixed; left: ${x}px; top: ${y}px;
          width: 40px; height: 40px; border-radius: 50%;
          border: 3px solid #2563eb;
          background: rgba(37, 99, 235, 0.18);
          box-shadow: 0 0 12px rgba(37, 99, 235, 0.6);
          transform: translate(-50%, -50%);
          animation: oeClickRing 0.9s ease-out forwards;
        }
      </style>
      <div class="ring"></div>
    `;
    document.documentElement.appendChild(host);
    setTimeout(() => { try { host.remove(); } catch {} }, 1000);
  }

  // Element highlight — a brief outline on whatever OE is about to
  // interact with. Element resolved by document.elementFromPoint(x,y).
  function highlightAt(x, y) {
    const el = document.elementFromPoint(x, y);
    if (!el || el === document.body || el === document.documentElement) return;
    const prev = {
      outline: el.style.outline,
      outlineOffset: el.style.outlineOffset,
      transition: el.style.transition,
    };
    el.style.transition = 'outline 0.2s ease-out';
    el.style.outline = '3px solid #2563eb';
    el.style.outlineOffset = '2px';
    setTimeout(() => {
      try {
        el.style.outline = prev.outline;
        el.style.outlineOffset = prev.outlineOffset;
        el.style.transition = prev.transition;
      } catch {}
    }, 700);
  }

  // Floating tooltip near the currently focused element showing what
  // text just got typed. Decays after a couple of seconds.
  function showTypeTooltip(text) {
    const focused = document.activeElement;
    if (!focused || focused === document.body) return;
    const rect = focused.getBoundingClientRect();
    const host = document.createElement('div');
    host.style.cssText = 'position:fixed;left:0;top:0;width:0;height:0;z-index:2147483647;pointer-events:none;';
    const sh = host.attachShadow({ mode: 'closed' });
    const safeText = String(text || '').replace(/[<>&"]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;'}[c]));
    sh.innerHTML = `
      <style>
        .tip {
          position: fixed;
          left: ${Math.round(rect.left)}px;
          top: ${Math.round(rect.bottom + 6)}px;
          background: #2563eb; color: #fff;
          padding: 4px 10px; border-radius: 4px;
          font: 600 12px/1.4 -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
          box-shadow: 0 2px 8px rgba(0,0,0,0.2);
          opacity: 0; animation: oeTipFade 1.8s ease-out forwards;
          max-width: 280px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;
        }
        @keyframes oeTipFade {
          0%  { opacity: 0; transform: translateY(-4px); }
          15% { opacity: 1; transform: translateY(0); }
          80% { opacity: 1; }
          100% { opacity: 0; transform: translateY(-4px); }
        }
      </style>
      <div class="tip">⌨ ${safeText}</div>
    `;
    document.documentElement.appendChild(host);
    setTimeout(() => { try { host.remove(); } catch {} }, 1900);
  }

  chrome.runtime.onMessage.addListener((msg) => {
    if (!msg || typeof msg !== 'object') return;
    if (msg.type === 'oe_activity_start') show(String(msg.action || ''));
    else if (msg.type === 'oe_activity_end') renderBase();
    else if (msg.type === 'oe_visual_click') {
      highlightAt(msg.x, msg.y);
      showClickRing(msg.x, msg.y);
    }
    else if (msg.type === 'oe_visual_type') showTypeTooltip(msg.text);
    else if (msg.type === 'oe_lease') {
      _leaseState = msg.state || 'none';
      _leaseExpiresAt = msg.expiresAt || null;
      renderBase();
    }
  });

  // On load, ask whether THIS tab is already leased — keeps the banner up
  // across same-origin navigations within a leased tab and after SW
  // respawn, and shows the paused bar after a cross-origin one.
  try {
    chrome.runtime.sendMessage({ type: 'get_lease_state' }, (resp) => {
      if (chrome.runtime.lastError) return;
      if (resp?.state && resp.state !== 'none') {
        _leaseState = resp.state;
        _leaseExpiresAt = resp.expiresAt || null;
        renderBase();
      }
    });
  } catch {}
})();

// OE Bridge ad-blocking engine (service worker side).
//
// Owns everything about *list-driven* blocking:
//   - which tiers are on, and the static declarativeNetRequest rulesets and
//     registered content scripts that follow from that;
//   - the per-site pause list, expressed both as dynamic allow rules (network)
//     and as excludeMatches on every registered script (cosmetic);
//   - the per-tab blocked counter behind the toolbar badge.
//
// Learned right-click rules stay in background.js. Nothing here reports to the
// OE server: tiers, the pause list, and counts are all browser-local.

export const TIERS = ['ads', 'trackers', 'annoyances'];

/** Mirrors tools/filter-parser.mjs: every blockable type except `main_frame`. */
const BLOCKABLE_RESOURCE_TYPES = Object.freeze([
  'sub_frame', 'stylesheet', 'script', 'image', 'font', 'object',
  'xmlhttprequest', 'ping', 'csp_report', 'media', 'websocket', 'other',
]);

const RULESET_FOR_TIER = { ads: 'oe_ads', trackers: 'oe_trackers', annoyances: 'oe_annoyances' };
const SURROGATE_RULESET_ID = 'oe_surrogates';

export const AD_BLOCK_ENABLED_KEY = 'adBlockingEnabled';
const TIERS_KEY = 'adBlockTiers';
const ALLOWLIST_KEY = 'adBlockAllowlist';
const BLOCKLIST_KEY = 'adBlockCustomDomains';

/** Trackers ride with ads by default; annoyances are opt-in because cookie and
 * newsletter rules are the most likely to interfere with a site. */
const DEFAULT_TIERS = Object.freeze({ ads: true, trackers: true, annoyances: false });

const REGISTRATION_PREFIX = 'oe-';
const REGISTRATION_CHUNK = 6;
const MAX_ALLOWLIST_HOSTS = 500;
const MAX_BLOCKLIST_HOSTS = 500;
/**
 * Dynamic rule ids are ours to allocate; keep them clear of the static
 * rulesets and give each list its own range so one sync never clears the
 * other's rules.
 */
const BLOCKLIST_RULE_ID_BASE = 800_000;
const ALLOWLIST_RULE_ID_BASE = 900_000;

/**
 * Priority ladder, highest first:
 *   5000  a site the user paused              (allowAllRequests)
 *   4500  a domain the user blocked by hand   (block)
 *   4000  an `$important` list exception      (allowAllRequests)
 *   3000  a list `$document` exception        (allowAllRequests)
 *   2500  a surrogate redirect
 *   2000  an `$important` list block
 *   1000  an ordinary list block or exception
 * A hand-added block therefore beats every list rule, because the user asked
 * for it explicitly, but still yields to their own pause on the current site.
 */
const BLOCKLIST_PRIORITY = 4500;

let _registrationsCache = null;
const _blockedCounts = new Map();

// --- preferences -------------------------------------------------------------

export async function getMasterEnabled() {
  const stored = await chrome.storage.local.get(AD_BLOCK_ENABLED_KEY);
  return stored?.[AD_BLOCK_ENABLED_KEY] !== false;
}

export async function getTierPreferences() {
  const stored = await chrome.storage.local.get(TIERS_KEY);
  const value = stored?.[TIERS_KEY];
  const result = { ...DEFAULT_TIERS };
  if (value && typeof value === 'object') {
    for (const tier of TIERS) {
      if (typeof value[tier] === 'boolean') result[tier] = value[tier];
    }
  }
  return result;
}

export async function setTierPreference(tier, enabled) {
  if (!TIERS.includes(tier)) throw new Error('unknown blocking tier');
  const tiers = await getTierPreferences();
  tiers[tier] = enabled === true;
  await chrome.storage.local.set({ [TIERS_KEY]: tiers });
  return tiers;
}

function normalizeHost(value) {
  const host = String(value || '').trim().toLowerCase();
  if (!host || host.length > 253) return null;
  return /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/.test(host) ? host : null;
}

export async function getAllowlist() {
  const stored = await chrome.storage.local.get(ALLOWLIST_KEY);
  const value = Array.isArray(stored?.[ALLOWLIST_KEY]) ? stored[ALLOWLIST_KEY] : [];
  const hosts = [];
  for (const entry of value) {
    const host = normalizeHost(entry);
    if (host && !hosts.includes(host)) hosts.push(host);
    if (hosts.length >= MAX_ALLOWLIST_HOSTS) break;
  }
  return hosts;
}

export async function setSiteAllowed(rawHost, allowed) {
  const host = normalizeHost(rawHost);
  if (!host) throw new Error('open a web page first');
  const current = await getAllowlist();
  const next = allowed
    ? [...new Set([host, ...current])].slice(0, MAX_ALLOWLIST_HOSTS)
    : current.filter(entry => entry !== host);
  await chrome.storage.local.set({ [ALLOWLIST_KEY]: next });
  return next;
}

export async function getBlocklist() {
  const stored = await chrome.storage.local.get(BLOCKLIST_KEY);
  const value = Array.isArray(stored?.[BLOCKLIST_KEY]) ? stored[BLOCKLIST_KEY] : [];
  const hosts = [];
  for (const entry of value) {
    const host = normalizeHost(entry);
    if (host && !hosts.includes(host)) hosts.push(host);
    if (hosts.length >= MAX_BLOCKLIST_HOSTS) break;
  }
  return hosts;
}

/**
 * Add or remove a hand-entered domain block. Blocking `example.com` also covers
 * its subdomains, so entering the registrable domain is usually what is wanted.
 */
export async function setDomainBlocked(rawHost, blocked) {
  const host = normalizeHost(rawHost);
  if (!host) throw new Error('enter a domain like log.byteoversea.com');
  const current = await getBlocklist();
  if (blocked && current.length >= MAX_BLOCKLIST_HOSTS && !current.includes(host)) {
    throw new Error(`the blocked-domain list is full (${MAX_BLOCKLIST_HOSTS})`);
  }
  const next = blocked
    ? [...new Set([host, ...current])].sort()
    : current.filter(entry => entry !== host);
  await chrome.storage.local.set({ [BLOCKLIST_KEY]: next });
  return next;
}

export async function isSiteAllowed(rawHost) {
  const host = normalizeHost(rawHost);
  if (!host) return false;
  const allowlist = await getAllowlist();
  // A pause on `example.com` covers `www.example.com` too.
  return allowlist.some(entry => host === entry || host.endsWith(`.${entry}`));
}

function hostPatterns(host) {
  return [`*://${host}/*`, `*://*.${host}/*`];
}

// --- generated filter payload ------------------------------------------------

async function loadRegistrations() {
  if (_registrationsCache) return _registrationsCache;
  try {
    const response = await fetch(chrome.runtime.getURL('filters/registrations.json'));
    const parsed = await response.json();
    _registrationsCache = Array.isArray(parsed) ? parsed : [];
  } catch {
    _registrationsCache = [];
  }
  return _registrationsCache;
}

export async function getBuildInfo() {
  try {
    const response = await fetch(chrome.runtime.getURL('filters/build-info.json'));
    return await response.json();
  } catch {
    return null;
  }
}

// --- network rulesets --------------------------------------------------------

async function syncRulesets(master, tiers) {
  const api = chrome?.declarativeNetRequest;
  if (!api?.updateEnabledRulesets) {
    throw new Error('This browser does not provide Manifest V3 network filtering.');
  }
  const enableRulesetIds = [];
  const disableRulesetIds = [];
  for (const tier of TIERS) {
    const id = RULESET_FOR_TIER[tier];
    (master && tiers[tier] ? enableRulesetIds : disableRulesetIds).push(id);
  }
  // Surrogates only matter while something is being blocked, and they must not
  // redirect anything once the user turns blocking off entirely.
  (master ? enableRulesetIds : disableRulesetIds).push(SURROGATE_RULESET_ID);
  await api.updateEnabledRulesets({ enableRulesetIds, disableRulesetIds });
}

/**
 * Rebuild both dynamic lists: paused sites get an `allowAllRequests` rule above
 * every other priority, and hand-added domains get a block just below it.
 *
 * Both are rewritten in one call so a toggle cannot leave the two halves
 * disagreeing, and each only clears ids from its own range.
 */
async function syncDynamicRules(allowlist, blocklist) {
  const api = chrome?.declarativeNetRequest;
  if (!api?.updateDynamicRules) return;
  const existing = await api.getDynamicRules().catch(() => []);
  const removeRuleIds = existing
    .filter(rule => rule.id >= BLOCKLIST_RULE_ID_BASE)
    .map(rule => rule.id);

  const addRules = [
    ...blocklist.slice(0, MAX_BLOCKLIST_HOSTS).map((host, index) => ({
      id: BLOCKLIST_RULE_ID_BASE + index,
      priority: BLOCKLIST_PRIORITY,
      action: { type: 'block' },
      // `main_frame` stays out: OE never blocks a top-level navigation, so a
      // hand-added domain still opens if it is typed into the address bar.
      condition: { urlFilter: `||${host}^`, resourceTypes: [...BLOCKABLE_RESOURCE_TYPES] },
    })),
    ...allowlist.slice(0, MAX_ALLOWLIST_HOSTS).map((host, index) => ({
      id: ALLOWLIST_RULE_ID_BASE + index,
      priority: 5000,
      action: { type: 'allowAllRequests' },
      condition: { urlFilter: `||${host}^`, resourceTypes: ['main_frame', 'sub_frame'] },
    })),
  ];
  await api.updateDynamicRules({ removeRuleIds, addRules });
}

// --- registered content scripts ---------------------------------------------

async function syncContentScripts(master, tiers, allowlist) {
  const api = chrome?.scripting;
  if (!api?.registerContentScripts) return;

  const all = await loadRegistrations();
  const excludeMatches = allowlist.flatMap(hostPatterns);
  const desired = new Map();
  if (master) {
    for (const entry of all) {
      if (!entry?.id || !tiers[entry.tier]) continue;
      const script = {
        id: entry.id,
        matches: entry.matches,
        runAt: 'document_start',
        allFrames: true,
        persistAcrossSessions: true,
      };
      if (entry.js) script.js = entry.js;
      if (entry.css) script.css = entry.css;
      if (entry.world) script.world = entry.world;
      if (excludeMatches.length) script.excludeMatches = excludeMatches;
      desired.set(entry.id, script);
    }
  }

  const registered = await api.getRegisteredContentScripts().catch(() => []);
  const ours = registered.filter(script => String(script.id || '').startsWith(REGISTRATION_PREFIX));

  const stale = ours.filter(script => !desired.has(script.id)).map(script => script.id);
  if (stale.length) await api.unregisterContentScripts({ ids: stale }).catch(() => {});

  const existingIds = new Set(ours.map(script => script.id));
  const toAdd = [...desired.values()].filter(script => !existingIds.has(script.id));
  const toUpdate = [...desired.values()].filter(script => {
    if (!existingIds.has(script.id)) return false;
    const current = ours.find(entry => entry.id === script.id);
    const before = (current?.excludeMatches || []).join('|');
    return before !== excludeMatches.join('|');
  });

  // Chrome rejects the whole call if any one script is invalid, so these go in
  // small batches: a bad bucket then costs its batch instead of all blocking.
  for (let index = 0; index < toAdd.length; index += REGISTRATION_CHUNK) {
    const batch = toAdd.slice(index, index + REGISTRATION_CHUNK);
    try {
      await api.registerContentScripts(batch);
    } catch (error) {
      console.warn('[OE Bridge] filter script registration failed:', error?.message || error);
    }
  }
  for (let index = 0; index < toUpdate.length; index += REGISTRATION_CHUNK) {
    const batch = toUpdate.slice(index, index + REGISTRATION_CHUNK)
      .map(script => ({ id: script.id, excludeMatches: script.excludeMatches || [] }));
    try {
      await api.updateContentScripts(batch);
    } catch (error) {
      console.warn('[OE Bridge] filter script update failed:', error?.message || error);
    }
  }
}

// --- blocked counters --------------------------------------------------------

export function blockedCountForTab(tabId) {
  return _blockedCounts.get(Number(tabId)) || 0;
}

function paintBadge(tabId, count) {
  if (!chrome?.action?.setBadgeText) return;
  const text = count > 999 ? '999+' : String(count || '');
  chrome.action.setBadgeText({ tabId, text: count ? text : '' }).catch(() => {});
  chrome.action.setBadgeBackgroundColor?.({ tabId, color: '#4b5563' }).catch(() => {});
}

export function resetTabCount(tabId) {
  const id = Number(tabId);
  if (!Number.isInteger(id)) return;
  _blockedCounts.delete(id);
  paintBadge(id, 0);
}

/**
 * `onRuleMatchedDebug` is only delivered to unpacked extensions, which is how
 * OE Bridge is installed. Where it is missing the counter simply stays absent
 * rather than reporting a wrong number.
 */
export function installCounters() {
  const api = chrome?.declarativeNetRequest;
  if (!api?.onRuleMatchedDebug?.addListener) return false;
  try {
    api.onRuleMatchedDebug.addListener(info => {
      const tabId = Number(info?.request?.tabId);
      if (!Number.isInteger(tabId) || tabId < 0) return;
      const next = (_blockedCounts.get(tabId) || 0) + 1;
      _blockedCounts.set(tabId, next);
      paintBadge(tabId, next);
    });
  } catch {
    return false;
  }
  chrome.tabs?.onRemoved?.addListener(tabId => _blockedCounts.delete(Number(tabId)));
  return true;
}

export function countersAvailable() {
  return Boolean(chrome?.declarativeNetRequest?.onRuleMatchedDebug);
}

// --- top-level sync ----------------------------------------------------------

let _syncTail = Promise.resolve();

/** Bring rulesets, dynamic allow rules, and registered scripts in line with the
 * stored preferences. Serialized so overlapping toggles cannot interleave. */
export function syncEverything() {
  const pending = _syncTail.then(async () => {
    const [master, tiers, allowlist, blocklist] = await Promise.all([
      getMasterEnabled(), getTierPreferences(), getAllowlist(), getBlocklist(),
    ]);
    await syncRulesets(master, tiers);
    await syncDynamicRules(master ? allowlist : [], master ? blocklist : []);
    await syncContentScripts(master, tiers, allowlist);
    return { master, tiers, allowlist, blocklist };
  });
  _syncTail = pending.then(() => undefined, () => undefined);
  return pending;
}

export async function setMasterEnabled(enabled) {
  await chrome.storage.local.set({ [AD_BLOCK_ENABLED_KEY]: enabled === true });
  await syncEverything();
  return enabled === true;
}

export async function engineStatus(siteHost) {
  const [master, tiers, allowlist, blocklist, buildInfo] = await Promise.all([
    getMasterEnabled(), getTierPreferences(), getAllowlist(), getBlocklist(), getBuildInfo(),
  ]);
  const paused = siteHost
    ? allowlist.some(entry => siteHost === entry || siteHost.endsWith(`.${entry}`))
    : false;
  return {
    enabled: master,
    tiers,
    paused,
    allowlistCount: allowlist.length,
    blockedDomains: blocklist,
    countersAvailable: countersAvailable(),
    filters: buildInfo
      ? { generated: buildInfo.generated, counts: buildInfo.counts, sources: buildInfo.sources?.length || 0 }
      : null,
  };
}

import {
  buildDiscoveryCandidates,
  claimBrowserPairing,
  discoverPairingService,
  generatePairingKeypair,
  requestBrowserPairing,
} from './pairing.js';

const POPUP_VERSION = chrome.runtime.getManifest().version;
console.log(`[OE Bridge popup] script loaded version=${POPUP_VERSION}`);

const $ = (id) => document.getElementById(id);

// Populate the input fields exactly once at popup open. The 3-second
// refresh loop only updates the STATUS pill — it must NOT touch the
// input fields, otherwise the user can't finish typing the server URL
// (every refresh overwrites the half-typed value with the empty stored
// value).
let _fieldsPopulated = false;
let _popupConfirmationId = null;
let _adBlockBusy = false;
let _adBlockReloadHint = false;

function populateFields(config) {
  if (_fieldsPopulated || !config) return;
  $('serverUrl').value = config.serverUrl || '';
  if (!$('pairingName').value) $('pairingName').value = config.name || defaultBrowserName();
  _fieldsPopulated = true;
}

// ── Browser-bound device-code pairing ──────────────────────────────────
const PENDING_PAIRING_KEY = 'browserPairingPending';
const BROWSER_CREDENTIAL_KEY = 'browserCredential';
const PENDING_CREDENTIAL_KEY = 'pendingBrowserCredential';
let _pairingPending = null;
let _pairingPollTimer = null;
let _pairingPollGeneration = 0;
let _pairingClaimInFlight = false;

function defaultBrowserName() {
  const platform = navigator.userAgentData?.platform || navigator.platform || '';
  return platform ? `OE Bridge on ${platform}` : 'OE Bridge';
}

function setPairingMessage(text, isError = false) {
  const target = _pairingPending ? $('pairingPendingMessage') : $('pairingStartMessage');
  if (!target) return;
  target.textContent = text || '';
  target.style.color = isError ? '#8a2424' : '#6b7280';
}

function renderPairingStart() {
  $('pairingStart').hidden = false;
  $('pairingPending').hidden = true;
  $('pairingComplete').hidden = true;
  _pairingPending = null;
}

function renderPendingPairing(pending) {
  _pairingPending = pending;
  $('pairingStart').hidden = true;
  $('pairingPending').hidden = false;
  $('pairingComplete').hidden = true;
  $('pairingCode').textContent = pending.userCode;
  $('pairingServer').textContent = `OE server: ${pending.serverUrl}`;
  $('pairingOpenApproval').hidden = !pending.approvalUrl;
  updatePairingCountdown();
}

function renderPairedCredential(credential) {
  $('pairingStart').hidden = true;
  $('pairingPending').hidden = true;
  $('pairingComplete').hidden = false;
  const who = String(credential?.userName || '').trim();
  $('pairingCompleteLabel').textContent = who ? `Securely paired for ${who}.` : 'Securely paired.';
  if (credential?.browserName) $('pairingName').value = credential.browserName;
}

function updatePairingCountdown() {
  if (!_pairingPending) return;
  const leftMs = Number(_pairingPending.expiresAt) - Date.now();
  if (leftMs <= 0) {
    $('pairingCountdown').textContent = 'This code has expired.';
    return;
  }
  const minutes = Math.floor(leftMs / 60_000);
  const seconds = Math.floor((leftMs % 60_000) / 1000);
  $('pairingCountdown').textContent = `Code expires in ${minutes}:${String(seconds).padStart(2, '0')}. Waiting for approval…`;
}

async function activeTabUrl() {
  try {
    const [tab] = await chrome.tabs.query({ active: true, currentWindow: true });
    return tab?.url || '';
  } catch {
    return '';
  }
}

function stopPairingPoll() {
  _pairingPollGeneration++;
  if (_pairingPollTimer) clearTimeout(_pairingPollTimer);
  _pairingPollTimer = null;
}

async function clearPendingPairing() {
  stopPairingPoll();
  _pairingPending = null;
  await chrome.storage.session.remove(PENDING_PAIRING_KEY);
}

async function beginBrowserPairing() {
  const button = $('pairingBegin');
  button.disabled = true;
  setPairingMessage('Looking for OpenEnsemble…');
  try {
    const statusResponse = await chrome.runtime.sendMessage({ type: 'get_status' }).catch(() => null);
    const configuredUrl = statusResponse?.config?.serverUrl || $('serverUrl').value.trim();
    const candidates = buildDiscoveryCandidates({
      explicitUrl: $('serverUrl').value.trim(),
      activeTabUrl: await activeTabUrl(),
      configuredUrl,
    });
    const service = await discoverPairingService({ candidates });
    setPairingMessage('Creating a browser-only identity…');
    const { publicKeyJwk, privateKeyJwk } = await generatePairingKeypair();
    const browserName = $('pairingName').value.trim() || defaultBrowserName();
    const request = await requestBrowserPairing({
      ...service,
      publicKeyJwk,
      browserName,
      extensionVersion: chrome.runtime.getManifest().version,
      sharedProfile: false,
    });
    const pending = {
      schema: 1,
      ...service,
      ...request,
      browserName,
      sharedProfile: false,
      publicKeyJwk,
      privateKeyJwk,
      createdAt: Date.now(),
    };
    // Opening OE closes the popup. Session storage lets pairing resume when
    // the popup is reopened; a browser restart destroys unfinished key data.
    await chrome.storage.session.set({ [PENDING_PAIRING_KEY]: pending });
    renderPendingPairing(pending);
    setPairingMessage('');
    schedulePairingPoll(0);
  } catch (error) {
    renderPairingStart();
    setPairingMessage(error?.message || String(error), true);
  } finally {
    button.disabled = false;
  }
}

async function finishApprovedPairing(pending, result) {
  // Background keeps this as a replacement candidate until a signed socket
  // succeeds. A working current browser credential is never overwritten by an
  // unproven replacement.
  const credential = {
    schema: 1,
    serverUrl: pending.serverUrl,
    credentialId: result.credentialId,
    userName: result.userName || '',
    browserName: pending.browserName,
    sharedProfile: Boolean(pending.sharedProfile),
    publicKeyJwk: pending.publicKeyJwk,
    privateKeyJwk: pending.privateKeyJwk,
    pairedAt: Date.now(),
  };
  const accepted = await chrome.runtime.sendMessage({
    type: 'browser_pairing_complete',
    credential,
  });
  if (!accepted?.ok) throw new Error(accepted?.error || 'background could not stage the browser credential');
  await clearPendingPairing();
  renderPairedCredential(credential);
}

async function checkPairingApproval({ manual = false, generation = _pairingPollGeneration } = {}) {
  const pending = _pairingPending;
  if (!pending || generation !== _pairingPollGeneration) return;
  if (_pairingClaimInFlight) {
    if (manual) setPairingMessage('Already checking with OE…');
    return;
  }
  if (Number(pending.expiresAt) <= Date.now()) {
    await clearPendingPairing();
    renderPairingStart();
    setPairingMessage('That pairing code expired. Start again for a new code.', true);
    return;
  }
  const checkButton = $('pairingCheck');
  if (_pairingPollTimer) clearTimeout(_pairingPollTimer);
  _pairingPollTimer = null;
  _pairingClaimInFlight = true;
  if (manual) checkButton.disabled = true;
  try {
    const result = await claimBrowserPairing(pending);
    if (generation !== _pairingPollGeneration) return;
    if (result.status === 'approved') {
      await finishApprovedPairing(pending, result);
      return;
    }
    if (result.status === 'denied' || result.status === 'expired') {
      await clearPendingPairing();
      renderPairingStart();
      setPairingMessage(
        result.status === 'denied' ? 'Pairing was declined in OE.' : 'That pairing code expired. Start again for a new code.',
        true,
      );
      return;
    }
    setPairingMessage(manual ? 'Not approved yet. Keep this code open in OE.' : '');
    schedulePairingPoll(result.pollIntervalMs || pending.pollIntervalMs);
  } catch (error) {
    if (generation !== _pairingPollGeneration) return;
    setPairingMessage(`${error?.message || String(error)} Retrying…`, true);
    schedulePairingPoll(Math.max(3_000, pending.pollIntervalMs || 2_000));
  } finally {
    _pairingClaimInFlight = false;
    checkButton.disabled = false;
  }
}

function schedulePairingPoll(delayMs) {
  if (!_pairingPending) return;
  if (_pairingPollTimer) clearTimeout(_pairingPollTimer);
  const generation = _pairingPollGeneration;
  _pairingPollTimer = setTimeout(() => {
    _pairingPollTimer = null;
    checkPairingApproval({ generation });
  }, Math.max(0, Number(delayMs) || 0));
}

async function initializePairing() {
  if (!$('pairingName').value) $('pairingName').value = defaultBrowserName();
  const [local, session] = await Promise.all([
    chrome.storage.local.get([BROWSER_CREDENTIAL_KEY, PENDING_CREDENTIAL_KEY]),
    chrome.storage.session.get(PENDING_PAIRING_KEY),
  ]);
  const pending = session?.[PENDING_PAIRING_KEY];
  if (pending && Number(pending.expiresAt) > Date.now() && pending.privateKeyJwk?.d) {
    renderPendingPairing(pending);
    schedulePairingPoll(0);
    return;
  }
  if (pending) await chrome.storage.session.remove(PENDING_PAIRING_KEY);
  const credential = local?.[PENDING_CREDENTIAL_KEY] || local?.[BROWSER_CREDENTIAL_KEY];
  if (credential?.credentialId && credential?.privateKeyJwk?.d) renderPairedCredential(credential);
  else renderPairingStart();
}

$('pairingBegin').addEventListener('click', beginBrowserPairing);
$('pairingCheck').addEventListener('click', () => checkPairingApproval({ manual: true }));
$('pairingOpenApproval').addEventListener('click', async () => {
  if (_pairingPending?.approvalUrl) await chrome.tabs.create({ url: _pairingPending.approvalUrl });
});
$('pairingCancel').addEventListener('click', async () => {
  await clearPendingPairing();
  renderPairingStart();
  setPairingMessage('Pairing cancelled. Your existing connection was not changed.');
});
$('pairingAgain').addEventListener('click', () => {
  renderPairingStart();
  setPairingMessage('Your current browser credential stays active until a new pairing succeeds.');
});
setInterval(updatePairingCountdown, 1_000);

function renderStatus(status) {
  const el = $('status');
  if (status.connected) {
    el.className = 'status ok';
    const since = status.since ? new Date(status.since).toLocaleTimeString() : '?';
    const userName = typeof status.userName === 'string' ? status.userName.trim() : '';
    el.replaceChildren();
    const label = document.createElement('b');
    label.textContent = userName ? `Connected ${userName}` : 'Connected';
    const meta = document.createElement('div');
    meta.className = 'meta';
    meta.textContent = `extId: ${status.extId ?? '?'}\nsince: ${since}\nserver: ${status.server ?? ''}`;
    meta.style.whiteSpace = 'pre-wrap';
    el.append(label, meta);
  } else if (status.lastError) {
    el.className = 'status bad';
    el.innerHTML = `<b>Disconnected</b><div class="meta">${status.lastError}</div>`;
  } else {
    el.className = 'status idle';
    el.textContent = 'Waiting for config…';
  }
  // Show the chat panel only when connected — no point asking Sydney
  // if the bridge can't reach OE.
  const panel = $('chatPanel');
  if (panel) panel.style.display = status.connected ? 'block' : 'none';
}

function renderPopupConfirmation(confirmation) {
  _popupConfirmationId = confirmation?.id || null;
  $('actionConfirmation').hidden = !_popupConfirmationId;
  if (!_popupConfirmationId) return;
  $('popupConfirmationSummary').textContent = confirmation.summary || 'Allow this browser action once?';
  $('popupConfirmationOrigin').textContent = [confirmation.pageTitle, confirmation.origin].filter(Boolean).join(' · ');
}

const AD_BLOCK_TIER_INPUTS = {
  ads: 'adBlockTierAds',
  trackers: 'adBlockTierTrackers',
  annoyances: 'adBlockTierAnnoyances',
};

function renderAdBlock(status) {
  if (!status?.ok) return;
  const enabledInput = $('adBlockEnabled');
  const statusEl = $('adBlockStatus');
  const actions = $('adBlockActions');
  const undo = $('adBlockUndo');
  const clear = $('adBlockClearSite');
  const tiers = $('adBlockTiers');
  const pauseRow = $('adBlockPauseRow');
  const pause = $('adBlockPause');
  statusEl.style.color = '#4b5563';
  enabledInput.checked = status.enabled === true;
  $('adBlockToggleLabel').textContent = status.enabled ? 'On' : 'Off';
  enabledInput.disabled = _adBlockBusy || status.networkAvailable === false;

  const available = status.networkAvailable !== false;
  const paused = status.paused === true;
  const count = Math.max(0, Number(status.learnedSiteCount) || 0);
  const blocked = Math.max(0, Number(status.blockedCount) || 0);

  for (const [tier, id] of Object.entries(AD_BLOCK_TIER_INPUTS)) {
    const input = $(id);
    input.checked = status.tiers?.[tier] === true;
    input.disabled = _adBlockBusy || !status.enabled || !available;
  }
  tiers.hidden = !available;
  pauseRow.hidden = !available || !status.siteHost;
  pause.textContent = paused ? `Resume blocking on ${status.siteHost}` : 'Pause on this site';
  pause.disabled = _adBlockBusy || !status.enabled;

  if (!available) {
    statusEl.textContent = 'This browser does not expose Manifest V3 network filtering.';
  } else if (!status.enabled) {
    statusEl.textContent = 'Off. Turn it on to block ads and trackers and apply anything you teach it.'
      + (_adBlockReloadHint ? ' Reload this page to restore requests that were already blocked.' : '');
  } else if (paused) {
    statusEl.textContent = `Paused on ${status.siteHost}. Nothing is blocked or hidden here until you resume.`
      + (_adBlockReloadHint ? ' Reload this page to apply the change.' : '');
  } else {
    const learned = count
      ? ` ${count} learned rule${count === 1 ? '' : 's'} also apply on ${status.siteHost || 'this site'}.`
      : '';
    const onThisPage = status.countersAvailable && blocked
      ? ` ${blocked} request${blocked === 1 ? '' : 's'} blocked on this page.`
      : '';
    statusEl.textContent = `Blocking locally.${onThisPage}${learned} Right-click anything it misses and choose “Block this ad with OE”.`
      + (_adBlockReloadHint ? ' Reload this page to apply the network setting to every request.' : '');
  }

  renderBlockedDomains(status);

  const filters = status.filters;
  $('adBlockFilterInfo').textContent = filters?.counts
    ? `Filter lists built ${filters.generated} · `
      + `${(filters.counts.tiers?.ads + filters.counts.tiers?.trackers + filters.counts.tiers?.annoyances).toLocaleString()} network rules · `
      + `${filters.counts.siteHosts.toLocaleString()} sites with specific rules`
    : '';

  actions.hidden = count === 0;
  undo.disabled = _adBlockBusy || !status.lastRuleId;
  clear.disabled = _adBlockBusy || count === 0;
}

/**
 * Rebuild the hand-blocked domain list. Rows are built with DOM calls rather
 * than markup so a stored hostname can never be interpreted as HTML.
 */
function renderBlockedDomains(status) {
  const section = $('adBlockDomains');
  const list = $('adBlockDomainList');
  const domains = Array.isArray(status.blockedDomains) ? status.blockedDomains : [];
  section.hidden = status.networkAvailable === false;
  $('adBlockDomainInput').disabled = _adBlockBusy || !status.enabled;
  $('adBlockDomainAdd').querySelector('button').disabled = _adBlockBusy || !status.enabled;

  list.replaceChildren();
  for (const host of domains) {
    const row = document.createElement('li');
    const label = document.createElement('code');
    label.textContent = host;
    const remove = document.createElement('button');
    remove.type = 'button';
    remove.textContent = 'Remove';
    remove.disabled = _adBlockBusy || !status.enabled;
    remove.addEventListener('click', () => runAdBlockAction(
      { type: 'set_adblock_domain_blocked', host, blocked: false },
      `Unblocking ${host}…`,
    ));
    row.append(label, remove);
    list.append(row);
  }
}

function showAdBlockError(text) {
  $('adBlockStatus').textContent = text || 'Ad-block settings could not be changed.';
  $('adBlockStatus').style.color = '#8a2424';
}

async function setAdBlockBusy(busy) {
  _adBlockBusy = busy;
  const ids = ['adBlockEnabled', 'adBlockUndo', 'adBlockClearSite', 'adBlockPause',
    'adBlockDomainInput', ...Object.values(AD_BLOCK_TIER_INPUTS)];
  for (const id of ids) $(id).disabled = busy;
  for (const button of $('adBlockDomains').querySelectorAll('button')) button.disabled = busy;
}

/** Shared wrapper for the ad-block controls: keep the panel busy, restore the
 * previous rendering if the worker rejects the change. */
async function runAdBlockAction(message, pending) {
  await setAdBlockBusy(true);
  $('adBlockStatus').style.color = '#4b5563';
  if (pending) $('adBlockStatus').textContent = pending;
  try {
    const response = await chrome.runtime.sendMessage(message);
    if (!response?.ok) throw new Error(response?.error || 'that change was not applied');
    _adBlockReloadHint = true;
    await setAdBlockBusy(false);
    renderAdBlock(response);
    return true;
  } catch (error) {
    await setAdBlockBusy(false);
    showAdBlockError(error?.message || String(error));
    try {
      const status = await chrome.runtime.sendMessage({ type: 'get_adblock_status' });
      if (status?.ok) {
        const reported = $('adBlockStatus').textContent;
        renderAdBlock(status);
        showAdBlockError(reported);
      }
    } catch {}
    return false;
  }
}

for (const [tier, id] of Object.entries(AD_BLOCK_TIER_INPUTS)) {
  $(id).addEventListener('change', () => runAdBlockAction(
    { type: 'set_adblock_tier', tier, enabled: $(id).checked },
    'Applying…',
  ));
}

$('adBlockDomainAdd').addEventListener('submit', async event => {
  event.preventDefault();
  const input = $('adBlockDomainInput');
  // Accept a pasted URL as readily as a bare hostname.
  const raw = input.value.trim().replace(/^[a-z]+:\/\//i, '').split(/[/?#]/)[0].replace(/^www\./i, '');
  if (!raw) return;
  const added = await runAdBlockAction(
    { type: 'set_adblock_domain_blocked', host: raw, blocked: true },
    `Blocking ${raw}…`,
  );
  // Leave a rejected entry in the box so the typo is visible and editable.
  if (added) input.value = '';
});

$('adBlockPause').addEventListener('click', () => {
  const resuming = $('adBlockPause').textContent.startsWith('Resume');
  return runAdBlockAction(
    { type: 'set_adblock_paused', paused: !resuming },
    resuming ? 'Resuming…' : 'Pausing…',
  );
});

$('adBlockEnabled').addEventListener('change', async () => {
  const desired = $('adBlockEnabled').checked;
  $('adBlockToggleLabel').textContent = desired ? 'On' : 'Off';
  await setAdBlockBusy(true);
  $('adBlockStatus').style.color = '#4b5563';
  $('adBlockStatus').textContent = desired ? 'Turning local ad blocking on…' : 'Turning local ad blocking off…';
  try {
    const response = await chrome.runtime.sendMessage({ type: 'set_adblock_enabled', enabled: desired });
    if (!response?.ok) throw new Error(response?.error || 'ad-block setting failed');
    _adBlockReloadHint = true;
    await setAdBlockBusy(false);
    renderAdBlock(response);
  } catch (error) {
    await setAdBlockBusy(false);
    $('adBlockEnabled').checked = !desired;
    $('adBlockToggleLabel').textContent = desired ? 'Off' : 'On';
    showAdBlockError(error?.message || String(error));
  }
});

$('adBlockUndo').addEventListener('click', async () => {
  await setAdBlockBusy(true);
  try {
    const response = await chrome.runtime.sendMessage({ type: 'adblock_undo_last' });
    if (!response?.ok) throw new Error(response?.error || 'undo failed');
    await setAdBlockBusy(false);
    renderAdBlock(response);
  } catch (error) {
    await setAdBlockBusy(false);
    showAdBlockError(error?.message || String(error));
  }
});

$('adBlockClearSite').addEventListener('click', async () => {
  if (!confirm('Remove every ad rule OE learned for this site?')) return;
  await setAdBlockBusy(true);
  try {
    const response = await chrome.runtime.sendMessage({ type: 'adblock_clear_site' });
    if (!response?.ok) throw new Error(response?.error || 'clear failed');
    await setAdBlockBusy(false);
    renderAdBlock(response);
  } catch (error) {
    await setAdBlockBusy(false);
    showAdBlockError(error?.message || String(error));
  }
});

$('popupConfirmationApprove').addEventListener('click', async () => {
  if (!_popupConfirmationId) return;
  const id = _popupConfirmationId;
  renderPopupConfirmation(null);
  const response = await chrome.runtime.sendMessage({ type: 'confirmation_respond', id, approved: true }).catch(() => null);
  if (!response?.ok) showError('That confirmation expired; nothing was done.');
});
$('popupConfirmationDecline').addEventListener('click', async () => {
  if (!_popupConfirmationId) return;
  const id = _popupConfirmationId;
  renderPopupConfirmation(null);
  await chrome.runtime.sendMessage({ type: 'confirmation_respond', id, approved: false }).catch(() => {});
});

// ── Capability lease controls ────────────────────────────────────────────
// Grants originate HERE (a click in extension UI) and nowhere else. The
// background broker denies every tab-touching server command without one.
function renderLease(lease) {
  const statusEl = $('leaseStatus');
  const revokeBtn = $('leaseRevoke');
  if (!statusEl || !revokeBtn) return;
  const tabs = (lease && Array.isArray(lease.tabs)) ? lease.tabs : [];
  if (tabs.length) {
    const until = new Date(lease.expiresAt).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    const active = tabs.filter(t => !t.suspended).length;
    const paused = tabs.length - active;
    statusEl.innerHTML = `🔓 <b>OE can use ${active} tab${active === 1 ? '' : 's'} until ${until}.</b>` +
      (paused ? ` ${paused} paused (tab left its granted site — press Resume on its banner).` : '') +
      ' Leased tabs show an amber banner.';
    revokeBtn.style.display = 'block';
  } else {
    statusEl.textContent = 'OE has no access to your tabs. Grant a short lease to let it read or act on the current tab.';
    revokeBtn.style.display = 'none';
  }
}

const leaseGrantBtn = $('leaseGrant');
const leaseRevokeBtn = $('leaseRevoke');
if (leaseGrantBtn) leaseGrantBtn.addEventListener('click', async () => {
  try {
    const resp = await chrome.runtime.sendMessage({ type: 'grant_lease' });
    if (resp?.ok) renderLease(resp.lease);
    else showError(resp?.error || 'lease grant failed');
  } catch (e) {
    showError(e?.message || String(e));
  }
});
if (leaseRevokeBtn) leaseRevokeBtn.addEventListener('click', async () => {
  try { await chrome.runtime.sendMessage({ type: 'revoke_lease' }); } catch {}
  renderLease(null);
});

// ── Chat with Sydney from the popup ──────────────────────────────────────
let _chatRequestId = null;
function appendReply(text, replace = false) {
  const el = $('chatReply');
  if (!el) return;
  if (replace) el.textContent = text;
  else el.textContent += text;
  el.scrollTop = el.scrollHeight;
}
function setReplyLabel(label) { appendReply(label, true); }

async function sendChat(text) {
  const t = String(text || '').trim();
  if (!t) return;
  setReplyLabel('…');
  const input = $('chatInput');
  if (input) input.value = '';
  _chatRequestId = `pp_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
  try {
    const resp = await chrome.runtime.sendMessage({ type: 'chat_send', requestId: _chatRequestId, text: t });
    if (!resp?.ok) appendReply(`\n\n[error: ${resp?.error || 'send failed'}]`, true);
  } catch (e) {
    appendReply(`\n\n[error: ${e?.message || String(e)}]`, true);
  }
}

chrome.runtime.onMessage.addListener((msg) => {
  if (!msg || msg.requestId !== _chatRequestId) return;
  if (msg.type === 'chat_event') {
    const ev = msg.event || {};
    if (ev.type === 'token' && typeof ev.text === 'string') {
      const el = $('chatReply');
      if (el && el.textContent === '…') el.textContent = '';
      appendReply(ev.text);
    } else if (ev.type === 'tool_call') {
      appendReply(`\n\n[${ev.name}…]\n`);
    } else if (ev.type === 'tool_result') {
      // Tool results are usually long — show a one-line preview, the
      // full text already lands as token events in the next assistant
      // turn anyway.
      const preview = (ev.preview || ev.text || '').slice(0, 120);
      appendReply(`\n  ↳ ${preview}${(ev.text||'').length > 120 ? '…' : ''}\n`);
    } else if (ev.type === 'error') {
      appendReply(`\n\n[error: ${ev.message || 'unknown'}]`);
    }
  } else if (msg.type === 'chat_done') {
    // Final newline so the reply doesn't run into the next user turn.
    appendReply('\n');
  } else if (msg.type === 'chat_error') {
    appendReply(`\n\n[server error: ${msg.message || 'unknown'}]`);
  }
});

const sendBtn = $('chatSend');
const clearBtn = $('chatClear');
const askPageBtn = $('askThisPage');
const chatInput = $('chatInput');
const sidepanelBtn = $('openSidepanel');
if (sendBtn) sendBtn.addEventListener('click', () => sendChat($('chatInput')?.value));
if (clearBtn) clearBtn.addEventListener('click', async () => {
  await chrome.runtime.sendMessage({ type: 'chat_history_clear' });
  setReplyLabel('');
});
if (askPageBtn) askPageBtn.addEventListener('click', async () => {
  // One-shot: snapshot the page now and send it with the question — no
  // lease is minted. Asking is consent to read this page once, nothing
  // more; only the explicit Allow button grants OE the ability to act.
  // Uses whatever is typed in the chat box as the question, else a default.
  const q = (chatInput?.value || '').trim();
  if (chatInput) chatInput.value = '';
  setReplyLabel('…');
  _chatRequestId = `pp_${Date.now()}_${Math.random().toString(36).slice(2,8)}`;
  try {
    const r = await chrome.runtime.sendMessage({ type: 'ask_page_oneshot', requestId: _chatRequestId, question: q });
    if (!r?.ok) appendReply(`\n\n[error: ${r?.error || 'ask failed'}]`, true);
  } catch (e) {
    appendReply(`\n\n[error: ${e?.message || String(e)}]`, true);
  }
});
if (sidepanelBtn) sidepanelBtn.addEventListener('click', async () => {
  // chrome.sidePanel.open() needs the user-gesture call stack — delegating
  // to the service worker silently fails. Open directly from the popup's
  // own click event instead.
  try {
    const win = await chrome.windows.getCurrent();
    await chrome.sidePanel.open({ windowId: win.id });
    window.close();
  } catch (e) {
